import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getAIClinicalReport = async (
  age: { years: string; months: string; days: string },
  selectedSymptoms: string[],
  triageLevel: string
) => {
  const prompt = `
    作为一名资深儿科急诊专家，请针对以下患儿情况提供一份深度的临床预检分析报告：

    患儿基本资料：
    - 年龄：${age.years}岁 ${age.months}月 ${age.days}天
    - 预检分级结果：${triageLevel}
    - 识别到的症状：${selectedSymptoms.join('、')}

    请按以下结构输出：
    1. 【病情评估】 分析当前症状的严重性及其在儿科急诊中的临床意义。
    2. 【潜在风险】 基于当前症状，列出可能出现的恶化指标或潜在并发症。
    3. 【临床路径建议】 建议的实验室检查（血常规、CRP、生化等）及影像学检查。
    4. 【干预重点】 护理及首接医生应重点监测的生命体征。

    语言风格：专业、严谨、简洁。
    格式：使用Markdown。
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("AI Report generation failed:", error);
    return "暂时无法生成AI临床报告，请检查网络连接或API配置。";
  }
};

import React, { useState, useMemo, useCallback } from 'react';
import { TRIAGE_CATEGORIES, TRIAGE_RESULT_CONFIG } from './constants';
import { TriageLevel, PatientState, TriageResult } from './types';
import { getAIClinicalReport } from './services/geminiService';

const App: React.FC = () => {
  const [patient, setPatient] = useState<PatientState>({
    ageYears: '',
    ageMonths: '',
    ageDays: '',
    selectedSymptoms: new Set(),
  });
  const [activeTab, setActiveTab] = useState(TRIAGE_CATEGORIES[0].id);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);

  const handleAgeChange = (field: keyof Omit<PatientState, 'selectedSymptoms'>, value: string) => {
    // Basic validation: positive integers only
    if (value !== '' && !/^\d+$/.test(value)) return;
    setPatient(prev => ({ ...prev, [field]: value }));
  };

  const toggleSymptom = (id: string) => {
    setPatient(prev => {
      const next = new Set(prev.selectedSymptoms);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return { ...prev, selectedSymptoms: next };
    });
    setAiReport(null); // Clear report if symptoms change
  };

  const reset = () => {
    setPatient({
      ageYears: '',
      ageMonths: '',
      ageDays: '',
      selectedSymptoms: new Set(),
    });
    setAiReport(null);
  };

  const currentTriage = useMemo((): TriageResult => {
    // 1. Calculate base level from symptoms
    let minLevelValue = 5;
    let foundLevel = false;

    patient.selectedSymptoms.forEach(id => {
      TRIAGE_CATEGORIES.forEach(cat => {
        const sym = cat.symptoms.find(s => s.id === id);
        if (sym) {
          minLevelValue = Math.min(minLevelValue, sym.level);
          foundLevel = true;
        }
      });
    });

    // 2. Adjust for age based on consensus rules
    // Rule: Newborns <= 24h are Level 2 (Critical) within 3-級以内
    // Rule: Infants < 3m are Level 3 within 3-級以内
    const years = parseInt(patient.ageYears) || 0;
    const months = parseInt(patient.ageMonths) || 0;
    const days = parseInt(patient.ageDays) || 0;

    if (years === 0 && months === 0 && days <= 1 && days > 0) {
      if (minLevelValue > 2) minLevelValue = 2; // Level 2 for newborns
    } else if (years === 0 && months < 3 && months >= 0) {
      if (minLevelValue > 3) minLevelValue = 3; // Level 3 for < 3m
    }

    return TRIAGE_RESULT_CONFIG[minLevelValue as TriageLevel];
  }, [patient]);

  const handleGenerateReport = async () => {
    setIsGenerating(true);
    const selectedSymptomsList: string[] = [];
    TRIAGE_CATEGORIES.forEach(cat => {
      cat.symptoms.forEach(s => {
        if (patient.selectedSymptoms.has(s.id)) {
          selectedSymptomsList.push(s.name);
        }
      });
    });

    const report = await getAIClinicalReport(
      { years: patient.ageYears, months: patient.ageMonths, days: patient.ageDays },
      selectedSymptomsList,
      currentTriage.levelName
    );
    setAiReport(report || "报告生成失败");
    setIsGenerating(false);
  };

  return (
    <div className="min-h-screen p-4 md:p-8 flex flex-col items-center">
      {/* Header */}
      <div className="w-full max-w-2xl text-center mb-8">
        <h1 className="text-3xl font-bold text-gray-800 tracking-tight">PETS</h1>
        <p className="text-gray-500 mt-1">Pediatric Emergency Triage System</p>
      </div>

      <div className="w-full max-w-2xl bg-white rounded-3xl shadow-xl overflow-hidden border border-gray-100 flex flex-col">
        {/* Age Input Section */}
        <div className="p-6 bg-slate-50/50 border-b border-gray-100">
          <div className="flex justify-between items-center mb-4">
            <span className="text-sm font-semibold text-gray-500 uppercase tracking-wider">患者年龄录入</span>
            <button onClick={reset} className="text-rose-500 hover:bg-rose-50 p-2 rounded-full transition-colors">
              <i className="fas fa-rotate-left"></i>
            </button>
          </div>
          <div className="grid grid-cols-3 gap-4">
            <div className="relative">
              <input
                type="text"
                value={patient.ageYears}
                onChange={(e) => handleAgeChange('ageYears', e.target.value)}
                placeholder="--"
                className="w-full bg-white border border-gray-200 rounded-2xl py-3 px-4 text-center text-lg font-medium focus:ring-2 focus:ring-violet-500 focus:border-transparent outline-none"
              />
              <span className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 text-sm">岁</span>
            </div>
            <div className="relative">
              <input
                type="text"
                value={patient.ageMonths}
                onChange={(e) => handleAgeChange('ageMonths', e.target.value)}
                placeholder="--"
                className="w-full bg-white border border-gray-200 rounded-2xl py-3 px-4 text-center text-lg font-medium focus:ring-2 focus:ring-violet-500 focus:border-transparent outline-none"
              />
              <span className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 text-sm">月</span>
            </div>
            <div className="relative">
              <input
                type="text"
                value={patient.ageDays}
                onChange={(e) => handleAgeChange('ageDays', e.target.value)}
                placeholder="--"
                className="w-full bg-white border border-gray-200 rounded-2xl py-3 px-4 text-center text-lg font-medium focus:ring-2 focus:ring-violet-500 focus:border-transparent outline-none"
              />
              <span className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 text-sm">天</span>
            </div>
          </div>
        </div>

        {/* Category Tabs */}
        <div className="p-4 grid grid-cols-2 md:grid-cols-4 gap-2 bg-slate-50/30">
          {TRIAGE_CATEGORIES.map(cat => (
            <button
              key={cat.id}
              onClick={() => setActiveTab(cat.id)}
              className={`py-2 px-3 rounded-xl text-xs font-semibold transition-all ${
                activeTab === cat.id
                  ? 'bg-violet-600 text-white shadow-lg shadow-violet-200'
                  : 'bg-white text-gray-500 border border-gray-100 hover:bg-gray-50'
              }`}
            >
              {cat.name}
            </button>
          ))}
        </div>

        {/* Symptoms List */}
        <div className="p-6 flex-1 min-h-[320px] max-h-[450px] overflow-y-auto custom-scrollbar">
          <div className="space-y-3">
            {TRIAGE_CATEGORIES.find(c => c.id === activeTab)?.symptoms.map(sym => (
              <button
                key={sym.id}
                onClick={() => toggleSymptom(sym.id)}
                className={`w-full text-left p-4 rounded-2xl border transition-all flex items-center justify-between group ${
                  patient.selectedSymptoms.has(sym.id)
                    ? 'border-violet-500 bg-violet-50'
                    : 'border-gray-100 bg-white hover:border-violet-200'
                }`}
              >
                <div className="flex items-center">
                  <span className={`text-sm font-medium ${patient.selectedSymptoms.has(sym.id) ? 'text-violet-700' : 'text-gray-700'}`}>
                    {sym.name}
                  </span>
                </div>
                {patient.selectedSymptoms.has(sym.id) ? (
                  <i className="fas fa-check-circle text-violet-500"></i>
                ) : (
                  <i className="far fa-circle text-gray-300 group-hover:text-violet-300"></i>
                )}
              </button>
            ))}
          </div>
        </div>

        {/* Result Card */}
        <div className={`p-8 ${currentTriage.zoneColor} text-white transition-colors duration-500 relative`}>
          <div className="flex justify-between items-start mb-6">
            <div>
              <div className="flex items-center gap-2 mb-2 opacity-90">
                <i className="fas fa-wave-square"></i>
                <span className="text-xs font-bold uppercase tracking-widest">分诊决策结果</span>
              </div>
              <h2 className="text-3xl font-extrabold tracking-tight">
                {currentTriage.levelName}
              </h2>
            </div>
            <div className="bg-white/20 backdrop-blur-md px-4 py-2 rounded-2xl text-center min-w-[100px]">
              <div className="text-[10px] font-bold opacity-80 mb-0.5">响应时限</div>
              <div className="text-lg font-black">{currentTriage.responseTime}</div>
            </div>
          </div>

          <div className="bg-black/10 backdrop-blur-sm rounded-2xl p-4 mb-6">
            <p className="text-sm font-medium leading-relaxed">
              {currentTriage.description}
            </p>
          </div>

          <div className="space-y-2 mb-8">
            <div className="flex items-center gap-2 text-xs font-bold opacity-80 mb-3">
              <i className="fas fa-bolt"></i>
              <span>临床干预要点</span>
            </div>
            {currentTriage.interventions.map((item, idx) => (
              <div key={idx} className="flex items-center gap-3 bg-white/20 backdrop-blur-sm p-3 rounded-xl border border-white/10">
                <span className="bg-white text-gray-800 text-[10px] font-bold h-5 w-5 rounded-full flex items-center justify-center">
                  {idx + 1}
                </span>
                <span className="text-sm font-semibold">{item}</span>
              </div>
            ))}
          </div>

          <button
            onClick={handleGenerateReport}
            disabled={isGenerating}
            className={`w-full py-4 px-6 bg-white text-gray-800 rounded-2xl font-bold flex items-center justify-center gap-2 shadow-xl hover:shadow-2xl transition-all hover:-translate-y-1 active:scale-95 ${isGenerating ? 'opacity-70 cursor-not-allowed' : ''}`}
          >
            {isGenerating ? (
              <i className="fas fa-circle-notch animate-spin"></i>
            ) : (
              <i className="fas fa-wand-magic-sparkles text-violet-600"></i>
            )}
            获取 AI 专家临床深度报告
          </button>
        </div>
      </div>

      {/* AI Report Modal/Section */}
      {aiReport && (
        <div className="w-full max-w-2xl mt-8 bg-white rounded-3xl p-8 shadow-lg border border-gray-100 animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-xl font-bold text-gray-800 flex items-center gap-2">
              <i className="fas fa-robot text-violet-500"></i>
              AI 专家深度报告
            </h3>
            <button onClick={() => setAiReport(null)} className="text-gray-400 hover:text-gray-600">
              <i className="fas fa-times"></i>
            </button>
          </div>
          <div className="prose prose-slate max-w-none text-gray-600 text-sm leading-relaxed whitespace-pre-wrap">
            {aiReport}
          </div>
          <div className="mt-8 p-4 bg-slate-50 rounded-2xl text-[10px] text-gray-400 text-center uppercase tracking-widest">
            报告由 Gemini 3 Pro AI 生成，仅供临床参考，决策请以主治医师意见为准
          </div>
        </div>
      )}

      {/* Footer Info */}
      <div className="mt-12 text-center text-gray-400 text-xs pb-8">
        <p>© 2024 PETS 儿科急诊预检分诊决策工具</p>
