import React, { useState, useMemo } from 'react';
import { TRIAGE_CATEGORIES, TRIAGE_RESULT_CONFIG } from './constants';
import { TriageLevel, PatientState, TriageResult, VitalSigns } from './types';
import { getAIClinicalReport } from './services/geminiService';

const App: React.FC = () => {
  const [patient, setPatient] = useState<PatientState>({
    ageYears: '',
    ageMonths: '',
    ageDays: '',
    vitals: {
      temperature: '',
      heartRate: '',
      respRate: '',
      bloodPressure: '',
      spo2: '',
      crt: '',
    },
    selectedSymptoms: new Set(),
  });
  const [activeTab, setActiveTab] = useState(TRIAGE_CATEGORIES[0].id);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);

  const handleAgeChange = (field: keyof Pick<PatientState, 'ageYears' | 'ageMonths' | 'ageDays'>, value: string) => {
    if (value !== '' && !/^\d+$/.test(value)) return;
    setPatient(prev => ({ ...prev, [field]: value }));
  };

  const handleVitalChange = (field: keyof VitalSigns, value: string) => {
    // Allow numbers and decimal points for vitals
    if (value !== '' && !/^\d*\.?\d*$/.test(value)) return;
    setPatient(prev => ({
      ...prev,
      vitals: { ...prev.vitals, [field]: value }
    }));
  };

  const toggleSymptom = (id: string) => {
    setPatient(prev => {
      const next = new Set(prev.selectedSymptoms);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return { ...prev, selectedSymptoms: next };
    });
    setAiReport(null);
  };

  const reset = () => {
    setPatient({
      ageYears: '',
      ageMonths: '',
      ageDays: '',
      vitals: {
        temperature: '',
        heartRate: '',
        respRate: '',
        bloodPressure: '',
        spo2: '',
        crt: '',
      },
      selectedSymptoms: new Set(),
    });
    setAiReport(null);
  };

  const triageReason = useMemo(() => {
    const reasons: string[] = [];

    // Check Age Constraints First
    const years = parseInt(patient.ageYears) || 0;
    const months = parseInt(patient.ageMonths) || 0;
    const days = parseInt(patient.ageDays) || 0;
    const totalMonths = (years * 12) + months;

    // Vital Signs Logic (Based on Shanghai Consensus)
    const t = parseFloat(patient.vitals.temperature);
    const hr = parseFloat(patient.vitals.heartRate);
    const rr = parseFloat(patient.vitals.respRate);
    const spo2 = parseFloat(patient.vitals.spo2);
    const crt = parseFloat(patient.vitals.crt);

    // SpO2 Logic
    if (spo2 > 0) {
      if (spo2 < 90) reasons.push("SpO2 < 90% (1级)");
      else if (spo2 <= 94) reasons.push("SpO2 90-94% (2级)");
    }

    // CRT Logic
    if (crt >= 3) reasons.push("CRT ≥ 3s (2级)");

    // Temperature Logic
    if (t > 0) {
      if (t >= 41 || t < 35) reasons.push("体温异常极值 (2级)");
      if (totalMonths < 3 && t >= 38) reasons.push("<3月龄患儿发热 (2级)");
    }

    // Age-appropriate Heart Rate and Respiratory Rate (Simplified Shanghai Consensus)
    if (hr > 0 || rr > 0) {
      if (years === 0 && months === 0 && days <= 28) { // Newborn
        if (hr > 180 || hr < 100) reasons.push("新生儿心率异常 (2级)");
        if (rr > 60 || rr < 30) reasons.push("新生儿呼吸异常 (2级)");
      } else if (totalMonths <= 12) { // Infant
        if (hr > 180 || hr < 80) reasons.push("婴儿心率异常 (2级)");
        if (rr > 50 || rr < 25) reasons.push("婴儿呼吸异常 (2级)");
      } else if (years <= 3) { // Toddler
        if (hr > 160 || hr < 70) reasons.push("幼儿心率异常 (2级)");
        if (rr > 40 || rr < 20) reasons.push("幼儿呼吸异常 (2级)");
      } else if (years <= 6) { // Preschool
        if (hr > 140 || hr < 60) reasons.push("学龄前心率异常 (2级)");
        if (rr > 30 || rr < 18) reasons.push("学龄前呼吸异常 (2级)");
      } else { // School age & Adolescent
        if (hr > 120 || hr < 50) reasons.push("年长儿心率异常 (2级)");
        if (rr > 24 || rr < 12) reasons.push("年长儿呼吸异常 (2级)");
      }
    }

    // Age-based specific rules
    if (years === 0 && months === 0 && days <= 1 && days > 0) {
      reasons.push("24小时内新生儿 (2级)");
    } else if (years === 0 && months < 3 && months >= 0) {
      reasons.push("<3月龄婴儿 (3级)");
    }

    return reasons;
  }, [patient]);

  const currentTriage = useMemo((): TriageResult => {
    let minLevelValue = 5;

    // 1. Symptom Based
    patient.selectedSymptoms.forEach(id => {
      TRIAGE_CATEGORIES.forEach(cat => {
        const sym = cat.symptoms.find(s => s.id === id);
        if (sym) {
          minLevelValue = Math.min(minLevelValue, sym.level);
        }
      });
    });

    // 2. Vital Signs & Age based overriding
    // SpO2 < 90 is Level 1
    const spo2 = parseFloat(patient.vitals.spo2);
    if (spo2 > 0 && spo2 < 90) minLevelValue = Math.min(minLevelValue, 1);

    // Most vital sign abnormalities lead to Level 2
    if (triageReason.some(r => r.includes("(1级)"))) minLevelValue = Math.min(minLevelValue, 1);
    else if (triageReason.some(r => r.includes("(2级)"))) minLevelValue = Math.min(minLevelValue, 2);
    else if (triageReason.some(r => r.includes("(3级)"))) minLevelValue = Math.min(minLevelValue, 3);

    return TRIAGE_RESULT_CONFIG[minLevelValue as TriageLevel];
  }, [patient, triageReason]);

  const handleGenerateReport = async () => {
    setIsGenerating(true);
    const selectedSymptomsList: string[] = [];
    TRIAGE_CATEGORIES.forEach(cat => {
      cat.symptoms.forEach(s => {
        if (patient.selectedSymptoms.has(s.id)) {
          selectedSymptomsList.push(s.name);
        }
      });
    });

    const report = await getAIClinicalReport(
      { years: patient.ageYears, months: patient.ageMonths, days: patient.ageDays },
      patient.vitals,
      selectedSymptomsList,
      currentTriage.levelName
    );
    setAiReport(report || "报告生成失败");
    setIsGenerating(false);
  };

  return (
    <div className="min-h-screen p-4 md:p-8 flex flex-col items-center">
      {/* Header */}
      <div className="w-full max-w-2xl text-center mb-8">
        <h1 className="text-3xl font-bold text-gray-800 tracking-tight">PETS-LZRYEK</h1>
        <p className="text-gray-500 mt-1">Pediatric Emergency Triage System - LZRYEK Edition</p>
      </div>

      <div className="w-full max-w-2xl bg-white rounded-3xl shadow-xl overflow-hidden border border-gray-100 flex flex-col">
        {/* Patient Info Section */}
        <div className="p-6 bg-slate-50/50 border-b border-gray-100">
          <div className="flex justify-between items-center mb-4">
            <span className="text-sm font-semibold text-gray-500 uppercase tracking-wider">患者基础信息录入</span>
            <button onClick={reset} className="text-rose-500 hover:bg-rose-50 p-2 rounded-full transition-colors">
              <i className="fas fa-rotate-left"></i>
            </button>
          </div>

          {/* Age Grid */}
          <div className="grid grid-cols-3 gap-3 mb-6">
            <div className="relative group">
              <label className="block text-[10px] text-gray-400 mb-1 ml-1 font-bold">岁</label>
              <input
                type="text"
                value={patient.ageYears}
                onChange={(e) => handleAgeChange('ageYears', e.target.value)}
                placeholder="--"
                className="w-full bg-white border border-gray-200 rounded-2xl py-2 px-3 text-center text-lg font-medium focus:ring-2 focus:ring-violet-500 focus:border-transparent outline-none transition-all"
              />
            </div>
            <div className="relative group">
              <label className="block text-[10px] text-gray-400 mb-1 ml-1 font-bold">月</label>
              <input
                type="text"
                value={patient.ageMonths}
                onChange={(e) => handleAgeChange('ageMonths', e.target.value)}
                placeholder="--"
                className="w-full bg-white border border-gray-200 rounded-2xl py-2 px-3 text-center text-lg font-medium focus:ring-2 focus:ring-violet-500 focus:border-transparent outline-none transition-all"
              />
            </div>
            <div className="relative group">
              <label className="block text-[10px] text-gray-400 mb-1 ml-1 font-bold">天</label>
              <input
                type="text"
                value={patient.ageDays}
                onChange={(e) => handleAgeChange('ageDays', e.target.value)}
                placeholder="--"
                className="w-full bg-white border border-gray-200 rounded-2xl py-2 px-3 text-center text-lg font-medium focus:ring-2 focus:ring-violet-500 focus:border-transparent outline-none transition-all"
              />
            </div>
          </div>

          {/* Vital Signs Grid */}
          <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
            {[
              { id: 'temperature', label: '体温', unit: '°C', color: 'focus:ring-orange-400' },
              { id: 'heartRate', label: '心率', unit: '次/分', color: 'focus:ring-rose-400' },
              { id: 'respRate', label: '呼吸', unit: '次/分', color: 'focus:ring-blue-400' },
              { id: 'bloodPressure', label: '血压', unit: 'mmHg', color: 'focus:ring-indigo-400' },
              { id: 'spo2', label: 'SpO2', unit: '%', color: 'focus:ring-cyan-400' },
              { id: 'crt', label: 'CRT', unit: '秒', color: 'focus:ring-emerald-400' },
            ].map((vital) => (
              <div key={vital.id} className="relative">
                <label className="block text-[10px] text-gray-400 mb-1 ml-1 font-bold uppercase">{vital.label}</label>
                <div className="relative">
                  <input
                    type="text"
                    value={patient.vitals[vital.id as keyof VitalSigns]}
                    onChange={(e) => handleVitalChange(vital.id as keyof VitalSigns, e.target.value)}
                    placeholder="--"
                    className={`w-full bg-white border border-gray-200 rounded-xl py-2 px-3 text-center text-sm font-semibold focus:ring-2 ${vital.color} focus:border-transparent outline-none transition-all`}
                  />
                  <span className="absolute right-2 bottom-2 text-[8px] text-gray-300 pointer-events-none">{vital.unit}</span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Category Tabs */}
        <div className="p-4 grid grid-cols-2 md:grid-cols-4 gap-2 bg-slate-50/30">
          {TRIAGE_CATEGORIES.map(cat => (
            <button
              key={cat.id}
              onClick={() => setActiveTab(cat.id)}
              className={`py-2 px-3 rounded-xl text-xs font-semibold transition-all ${
                activeTab === cat.id
                  ? 'bg-violet-600 text-white shadow-lg shadow-violet-200'
                  : 'bg-white text-gray-500 border border-gray-100 hover:bg-gray-50'
              }`}
            >
              {cat.name}
            </button>
          ))}
        </div>

        {/* Symptoms List */}
        <div className="p-6 flex-1 min-h-[320px] max-h-[450px] overflow-y-auto custom-scrollbar">
          <div className="space-y-3">
            {TRIAGE_CATEGORIES.find(c => c.id === activeTab)?.symptoms.map(sym => (
              <button
                key={sym.id}
                onClick={() => toggleSymptom(sym.id)}
                className={`w-full text-left p-4 rounded-2xl border transition-all flex items-center justify-between group ${
                  patient.selectedSymptoms.has(sym.id)
                    ? 'border-violet-500 bg-violet-50'
                    : 'border-gray-100 bg-white hover:border-violet-200'
                }`}
              >
                <div className="flex items-center">
                  <span className={`text-sm font-medium ${patient.selectedSymptoms.has(sym.id) ? 'text-violet-700' : 'text-gray-700'}`}>
                    {sym.name}
                  </span>
                </div>
                {patient.selectedSymptoms.has(sym.id) ? (
                  <i className="fas fa-check-circle text-violet-500"></i>
                ) : (
                  <i className="far fa-circle text-gray-300 group-hover:text-violet-300"></i>
                )}
              </button>
            ))}
          </div>
        </div>

        {/* Result Card */}
        <div className={`p-8 ${currentTriage.zoneColor} text-white transition-colors duration-500 relative`}>
          <div className="flex justify-between items-start mb-6">
            <div>
              <div className="flex items-center gap-2 mb-2 opacity-90">
                <i className="fas fa-wave-square"></i>
                <span className="text-xs font-bold uppercase tracking-widest">分诊决策结果</span>
              </div>
              <h2 className="text-3xl font-extrabold tracking-tight">
                {currentTriage.levelName}
              </h2>
              {triageReason.length > 0 && (
                <div className="mt-2 flex flex-wrap gap-2">
                  {triageReason.map((reason, i) => (
                    <span key={i} className="text-[10px] bg-white/20 px-2 py-0.5 rounded-full font-medium">
                      {reason}
                    </span>
                  ))}
                </div>
              )}
            </div>
            <div className="bg-white/20 backdrop-blur-md px-4 py-2 rounded-2xl text-center min-w-[100px]">
              <div className="text-[10px] font-bold opacity-80 mb-0.5">响应时限</div>
              <div className="text-lg font-black">{currentTriage.responseTime}</div>
            </div>
          </div>

          <div className="bg-black/10 backdrop-blur-sm rounded-2xl p-4 mb-6">
            <p className="text-sm font-medium leading-relaxed">
              {currentTriage.description}
            </p>
          </div>

          <div className="space-y-2 mb-8">
            <div className="flex items-center gap-2 text-xs font-bold opacity-80 mb-3">
              <i className="fas fa-bolt"></i>
              <span>临床干预要点</span>
            </div>
            {currentTriage.interventions.map((item, idx) => (
              <div key={idx} className="flex items-center gap-3 bg-white/20 backdrop-blur-sm p-3 rounded-xl border border-white/10">
                <span className="bg-white text-gray-800 text-[10px] font-bold h-5 w-5 rounded-full flex items-center justify-center">
                  {idx + 1}
                </span>
                <span className="text-sm font-semibold">{item}</span>
              </div>
            ))}
          </div>

          <button
            onClick={handleGenerateReport}
            disabled={isGenerating}
            className={`w-full py-4 px-6 bg-white text-gray-800 rounded-2xl font-bold flex items-center justify-center gap-2 shadow-xl hover:shadow-2xl transition-all hover:-translate-y-1 active:scale-95 ${isGenerating ? 'opacity-70 cursor-not-allowed' : ''}`}
          >
            {isGenerating ? (
              <i className="fas fa-circle-notch animate-spin"></i>
            ) : (
              <i className="fas fa-wand-magic-sparkles text-violet-600"></i>
            )}
            获取 AI 专家临床深度报告
          </button>
        </div>
      </div>

      {/* AI Report Modal/Section */}
      {aiReport && (
        <div className="w-full max-w-2xl mt-8 bg-white rounded-3xl p-8 shadow-lg border border-gray-100 animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-xl font-bold text-gray-800 flex items-center gap-2">
              <i className="fas fa-robot text-violet-500"></i>
              AI 专家深度报告
            </h3>
            <button onClick={() => setAiReport(null)} className="text-gray-400 hover:text-gray-600">
              <i className="fas fa-times"></i>
            </button>
          </div>
          <div className="prose prose-slate max-w-none text-gray-600 text-sm leading-relaxed whitespace-pre-wrap">
            {aiReport}
          </div>
          <div className="mt-8 p-4 bg-slate-50 rounded-2xl text-[10px] text-gray-400 text-center uppercase tracking-widest">
            报告由 Gemini 3 Pro AI 生成，仅供临床参考，决策请以主治医师意见为准
          </div>
        </div>
      )}

      {/* Footer Info */}
      <div className="mt-12 text-center text-gray-400 text-xs pb-8">
        <p>© 2024 PETS-LZRYEK 儿科急诊预检分诊决策工具</p>
        <p className="mt-1">依据《儿科急诊预检分诊专家共识（上海）》2022版构建</p>
      </div>
    </div>
  );
};

export default App;

export enum TriageLevel {
  L1 = 1, // 濒危 (Endangered)
  L2 = 2, // 危重 (Critical)
  L3 = 3, // 急症 (Urgent)
  L4 = 4, // 亚急症 (Sub-urgent)
  L5 = 5  // 非急症 (Non-urgent)
}

export interface Symptom {
  id: string;
  name: string;
  level: TriageLevel;
  description?: string;
}

export interface TriageCategory {
  id: string;
  name: string;
  symptoms: Symptom[];
}

export interface TriageResult {
  level: TriageLevel;
  levelName: string;
  responseTime: string;
  zone: string;
  zoneColor: string;
  description: string;
  interventions: string[];
}

export interface VitalSigns {
  temperature: string;
  heartRate: string;
  respRate: string;
  bloodPressure: string;
  spo2: string;
  crt: string;
}

export interface PatientState {
  ageYears: string;
  ageMonths: string;
  ageDays: string;
  weight: string;
  vitals: VitalSigns;
  selectedSymptoms: Set<string>;
}

import { GoogleGenAI } from "@google/genai";
import { VitalSigns } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getAIClinicalReport = async (
  age: { years: string; months: string; days: string },
  weight: string,
  vitals: VitalSigns,
  selectedSymptoms: string[],
  triageLevel: string
) => {
  const prompt = `
    作为一名资深儿科急诊专家，请针对以下患儿情况提供一份深度的临床预检分析报告：

    患儿基本资料：
    - 年龄：${age.years}岁 ${age.months}月 ${age.days}天
    - 体重：${weight || '未录入'}kg
    - 生命体征：
      * 体温: ${vitals.temperature || '未录入'}°C
      * 心率: ${vitals.heartRate || '未录入'}次/分
      * 呼吸: ${vitals.respRate || '未录入'}次/分
      * 血压: ${vitals.bloodPressure || '未录入'}mmHg
      * SpO2: ${vitals.spo2 || '未录入'}%
      * CRT: ${vitals.crt || '未录入'}秒
    - 预检分级结果：${triageLevel}
    - 识别到的症状：${selectedSymptoms.join('、') || '无特异性症状'}

    请按以下结构输出：
    1. 【病情评估】 分析当前生命体征和症状的严重性及其在儿科急诊中的临床意义。
    2. 【潜在风险】 基于当前指标，列出可能出现的恶化指标或潜在并发症。
    3. 【临床路径建议】 建议的实验室检查（血常规、CRP、生化等）及影像学检查。
    4. 【干预重点】 护理及首接医生应重点监测的生命体征。

    语言风格：专业、严谨、简洁。
    格式：使用Markdown。
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("AI Report generation failed:", error);
    return "暂时无法生成AI临床报告，请检查网络连接或API配置。";
  }
};

import React, { useState, useMemo } from 'react';
import { TRIAGE_CATEGORIES, TRIAGE_RESULT_CONFIG } from './constants';
import { TriageLevel, PatientState, TriageResult, VitalSigns } from './types';
import { getAIClinicalReport } from './services/geminiService';

const App: React.FC = () => {
  const [patient, setPatient] = useState<PatientState>({
    ageYears: '',
    ageMonths: '',
    ageDays: '',
    weight: '',
    vitals: {
      temperature: '',
      heartRate: '',
      respRate: '',
      bloodPressure: '',
      spo2: '',
      crt: '',
    },
    selectedSymptoms: new Set(),
  });
  const [activeTab, setActiveTab] = useState(TRIAGE_CATEGORIES[0].id);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);

  const handleAgeChange = (field: keyof Pick<PatientState, 'ageYears' | 'ageMonths' | 'ageDays'>, value: string) => {
    if (value !== '' && !/^\d+$/.test(value)) return;
    setPatient(prev => ({ ...prev, [field]: value }));
  };

  const handleWeightChange = (value: string) => {
    if (value !== '' && !/^\d*\.?\d*$/.test(value)) return;
    setPatient(prev => ({ ...prev, weight: value }));
  };

  const handleVitalChange = (field: keyof VitalSigns, value: string) => {
    // Allow numbers and decimal points for vitals
    if (value !== '' && !/^\d*\.?\d*$/.test(value)) return;
    setPatient(prev => ({
      ...prev,
      vitals: { ...prev.vitals, [field]: value }
    }));
  };

  const toggleSymptom = (id: string) => {
    setPatient(prev => {
      const next = new Set(prev.selectedSymptoms);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return { ...prev, selectedSymptoms: next };
    });
    setAiReport(null);
  };

  const reset = () => {
    setPatient({
      ageYears: '',
      ageMonths: '',
      ageDays: '',
      weight: '',
      vitals: {
        temperature: '',
        heartRate: '',
        respRate: '',
        bloodPressure: '',
        spo2: '',
        crt: '',
      },
      selectedSymptoms: new Set(),
    });
    setAiReport(null);
  };

  const triageReason = useMemo(() => {
    const reasons: string[] = [];

    // Check Age Constraints First
    const years = parseInt(patient.ageYears) || 0;
    const months = parseInt(patient.ageMonths) || 0;
    const days = parseInt(patient.ageDays) || 0;
    const totalMonths = (years * 12) + months;

    // Vital Signs Logic (Based on Shanghai Consensus)
    const t = parseFloat(patient.vitals.temperature);
    const hr = parseFloat(patient.vitals.heartRate);
    const rr = parseFloat(patient.vitals.respRate);
    const spo2 = parseFloat(patient.vitals.spo2);
    const crt = parseFloat(patient.vitals.crt);

    // SpO2 Logic
    if (spo2 > 0) {
      if (spo2 < 90) reasons.push("SpO2 < 90% (1级)");
      else if (spo2 <= 94) reasons.push("SpO2 90-94% (2级)");
    }

    // CRT Logic
    if (crt >= 3) reasons.push("CRT ≥ 3s (2级)");

    // Temperature Logic
    if (t > 0) {
      if (t >= 41 || t < 35) reasons.push("体温异常极值 (2级)");
      if (totalMonths < 3 && t >= 38) reasons.push("<3月龄患儿发热 (2级)");
    }

    // Age-appropriate Heart Rate and Respiratory Rate (Simplified Shanghai Consensus)
    if (hr > 0 || rr > 0) {
      if (years === 0 && months === 0 && days <= 28) { // Newborn
        if (hr > 180 || hr < 100) reasons.push("新生儿心率异常 (2级)");
        if (rr > 60 || rr < 30) reasons.push("新生儿呼吸异常 (2级)");
      } else if (totalMonths <= 12) { // Infant
        if (hr > 180 || hr < 80) reasons.push("婴儿心率异常 (2级)");
        if (rr > 50 || rr < 25) reasons.push("婴儿呼吸异常 (2级)");
      } else if (years <= 3) { // Toddler
        if (hr > 160 || hr < 70) reasons.push("幼儿心率异常 (2级)");
        if (rr > 40 || rr < 20) reasons.push("幼儿呼吸异常 (2级)");
      } else if (years <= 6) { // Preschool
        if (hr > 140 || hr < 60) reasons.push("学龄前心率异常 (2级)");
        if (rr > 30 || rr < 18) reasons.push("学龄前呼吸异常 (2级)");
      } else { // School age & Adolescent
        if (hr > 120 || hr < 50) reasons.push("年长儿心率异常 (2级)");
        if (rr > 24 || rr < 12) reasons.push("年长儿呼吸异常 (2级)");
      }
    }

    // Age-based specific rules
    if (years === 0 && months === 0 && days <= 1 && days > 0) {
      reasons.push("24小时内新生儿 (2级)");
    } else if (years === 0 && months < 3 && months >= 0) {
      reasons.push("<3月龄婴儿 (3级)");
    }

    return reasons;
  }, [patient]);

  const currentTriage = useMemo((): TriageResult => {
    let minLevelValue = 5;

    // 1. Symptom Based
    patient.selectedSymptoms.forEach(id => {
      TRIAGE_CATEGORIES.forEach(cat => {
        const sym = cat.symptoms.find(s => s.id === id);
        if (sym) {
          minLevelValue = Math.min(minLevelValue, sym.level);
        }
      });
    });

    // 2. Vital Signs & Age based overriding
    const spo2 = parseFloat(patient.vitals.spo2);
    if (spo2 > 0 && spo2 < 90) minLevelValue = Math.min(minLevelValue, 1);

    if (triageReason.some(r => r.includes("(1级)"))) minLevelValue = Math.min(minLevelValue, 1);
    else if (triageReason.some(r => r.includes("(2级)"))) minLevelValue = Math.min(minLevelValue, 2);
    else if (triageReason.some(r => r.includes("(3级)"))) minLevelValue = Math.min(minLevelValue, 3);

    return TRIAGE_RESULT_CONFIG[minLevelValue as TriageLevel];
  }, [patient, triageReason]);

  const handleGenerateReport = async () => {
    setIsGenerating(true);
    const selectedSymptomsList: string[] = [];
    TRIAGE_CATEGORIES.forEach(cat => {
      cat.symptoms.forEach(s => {
        if (patient.selectedSymptoms.has(s.id)) {
          selectedSymptomsList.push(s.name);
        }
      });
    });

    const report = await getAIClinicalReport(
      { years: patient.ageYears, months: patient.ageMonths, days: patient.ageDays },
      patient.weight,
      patient.vitals,
      selectedSymptomsList,
      currentTriage.levelName
    );
    setAiReport(report || "报告生成失败");
    setIsGenerating(false);
  };

  return (
    <div className="min-h-screen p-4 md:p-8 flex flex-col items-center">
      {/* Header */}
      <div className="w-full max-w-2xl text-center mb-8">
        <h1 className="text-3xl font-bold text-gray-800 tracking-tight">PETS-LZRYEK</h1>
        <p className="text-gray-500 mt-1">Pediatric Emergency Triage System - LZRYEK Edition</p>
      </div>

      <div className="w-full max-w-2xl bg-white rounded-3xl shadow-xl overflow-hidden border border-gray-100 flex flex-col">
        {/* Patient Info Section */}
        <div className="p-6 bg-slate-50/50 border-b border-gray-100">
          <div className="flex justify-between items-center mb-4">
            <span className="text-sm font-semibold text-gray-500 uppercase tracking-wider">患者基础信息录入</span>
            <button onClick={reset} className="text-rose-500 hover:bg-rose-50 p-2 rounded-full transition-colors">
              <i className="fas fa-rotate-left"></i>
            </button>
          </div>

          {/* Age & Weight Grid */}
          <div className="grid grid-cols-4 gap-3 mb-6">
            <div className="relative group">
              <label className="block text-[10px] text-gray-400 mb-1 ml-1 font-bold uppercase">岁</label>
              <input
                type="text"
                value={patient.ageYears}
                onChange={(e) => handleAgeChange('ageYears', e.target.value)}
                placeholder="--"
                className="w-full bg-white border border-gray-200 rounded-2xl py-2 px-3 text-center text-lg font-medium focus:ring-2 focus:ring-violet-500 focus:border-transparent outline-none transition-all"
              />
            </div>
            <div className="relative group">
              <label className="block text-[10px] text-gray-400 mb-1 ml-1 font-bold uppercase">月</label>
              <input
                type="text"
                value={patient.ageMonths}
                onChange={(e) => handleAgeChange('ageMonths', e.target.value)}
                placeholder="--"
                className="w-full bg-white border border-gray-200 rounded-2xl py-2 px-3 text-center text-lg font-medium focus:ring-2 focus:ring-violet-500 focus:border-transparent outline-none transition-all"
              />
            </div>
            <div className="relative group">
              <label className="block text-[10px] text-gray-400 mb-1 ml-1 font-bold uppercase">天</label>
              <input
                type="text"
                value={patient.ageDays}
                onChange={(e) => handleAgeChange('ageDays', e.target.value)}
                placeholder="--"
                className="w-full bg-white border border-gray-200 rounded-2xl py-2 px-3 text-center text-lg font-medium focus:ring-2 focus:ring-violet-500 focus:border-transparent outline-none transition-all"
              />
            </div>
            <div className="relative group">
              <label className="block text-[10px] text-gray-400 mb-1 ml-1 font-bold uppercase">体重 (kg)</label>
              <input
                type="text"
                value={patient.weight}
                onChange={(e) => handleWeightChange(e.target.value)}
                placeholder="--"
                className="w-full bg-white border border-gray-200 rounded-2xl py-2 px-3 text-center text-lg font-medium focus:ring-2 focus:ring-amber-500 focus:border-transparent outline-none transition-all"
              />
            </div>
          </div>

          {/* Vital Signs Grid */}
          <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
            {[
              { id: 'temperature', label: '体温', unit: '°C', color: 'focus:ring-orange-400' },
              { id: 'heartRate', label: '心率', unit: '次/分', color: 'focus:ring-rose-400' },
              { id: 'respRate', label: '呼吸', unit: '次/分', color: 'focus:ring-blue-400' },
              { id: 'bloodPressure', label: '血压', unit: 'mmHg', color: 'focus:ring-indigo-400' },
              { id: 'spo2', label: 'SpO2', unit: '%', color: 'focus:ring-cyan-400' },
              { id: 'crt', label: 'CRT', unit: '秒', color: 'focus:ring-emerald-400' },
            ].map((vital) => (
              <div key={vital.id} className="relative">
                <label className="block text-[10px] text-gray-400 mb-1 ml-1 font-bold uppercase">{vital.label}</label>
                <div className="relative">
                  <input
                    type="text"
                    value={patient.vitals[vital.id as keyof VitalSigns]}
                    onChange={(e) => handleVitalChange(vital.id as keyof VitalSigns, e.target.value)}
                    placeholder="--"
                    className={`w-full bg-white border border-gray-200 rounded-xl py-2 px-3 text-center text-sm font-semibold focus:ring-2 ${vital.color} focus:border-transparent outline-none transition-all`}
                  />
                  <span className="absolute right-2 bottom-2 text-[8px] text-gray-300 pointer-events-none">{vital.unit}</span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Category Tabs */}
        <div className="p-4 grid grid-cols-2 md:grid-cols-4 gap-2 bg-slate-50/30">
          {TRIAGE_CATEGORIES.map(cat => (
            <button
              key={cat.id}
              onClick={() => setActiveTab(cat.id)}
              className={`py-2 px-3 rounded-xl text-xs font-semibold transition-all ${
                activeTab === cat.id
                  ? 'bg-violet-600 text-white shadow-lg shadow-violet-200'
                  : 'bg-white text-gray-500 border border-gray-100 hover:bg-gray-50'
              }`}
            >
              {cat.name}
            </button>
          ))}
        </div>

        {/* Symptoms List */}
        <div className="p-6 flex-1 min-h-[320px] max-h-[450px] overflow-y-auto custom-scrollbar">
          <div className="space-y-3">
            {TRIAGE_CATEGORIES.find(c => c.id === activeTab)?.symptoms.map(sym => (
              <button
                key={sym.id}
                onClick={() => toggleSymptom(sym.id)}
                className={`w-full text-left p-4 rounded-2xl border transition-all flex items-center justify-between group ${
                  patient.selectedSymptoms.has(sym.id)
                    ? 'border-violet-500 bg-violet-50'
                    : 'border-gray-100 bg-white hover:border-violet-200'
                }`}
              >
                <div className="flex items-center">
                  <span className={`text-sm font-medium ${patient.selectedSymptoms.has(sym.id) ? 'text-violet-700' : 'text-gray-700'}`}>
                    {sym.name}
                  </span>
                </div>
                {patient.selectedSymptoms.has(sym.id) ? (
                  <i className="fas fa-check-circle text-violet-500"></i>
                ) : (
                  <i className="far fa-circle text-gray-300 group-hover:text-violet-300"></i>
                )}
              </button>
            ))}
          </div>
        </div>

        {/* Result Card */}
        <div className={`p-8 ${currentTriage.zoneColor} text-white transition-colors duration-500 relative`}>
          <div className="flex justify-between items-start mb-6">
            <div>
              <div className="flex items-center gap-2 mb-2 opacity-90">
                <i className="fas fa-wave-square"></i>
                <span className="text-xs font-bold uppercase tracking-widest">分诊决策结果</span>
              </div>
              <h2 className="text-3xl font-extrabold tracking-tight">
                {currentTriage.levelName}
              </h2>
              {triageReason.length > 0 && (
                <div className="mt-2 flex flex-wrap gap-2">
                  {triageReason.map((reason, i) => (
                    <span key={i} className="text-[10px] bg-white/20 px-2 py-0.5 rounded-full font-medium">
                      {reason}
                    </span>
                  ))}
                </div>
              )}
            </div>
            <div className="bg-white/20 backdrop-blur-md px-4 py-2 rounded-2xl text-center min-w-[100px]">
              <div className="text-[10px] font-bold opacity-80 mb-0.5">响应时限</div>
              <div className="text-lg font-black">{currentTriage.responseTime}</div>
            </div>
          </div>

          <div className="bg-black/10 backdrop-blur-sm rounded-2xl p-4 mb-6">
            <p className="text-sm font-medium leading-relaxed">
              {currentTriage.description}
            </p>
          </div>

          <div className="space-y-2 mb-8">
            <div className="flex items-center gap-2 text-xs font-bold opacity-80 mb-3">
              <i className="fas fa-bolt"></i>
              <span>临床干预要点</span>
            </div>
            {currentTriage.interventions.map((item, idx) => (
              <div key={idx} className="flex items-center gap-3 bg-white/20 backdrop-blur-sm p-3 rounded-xl border border-white/10">
                <span className="bg-white text-gray-800 text-[10px] font-bold h-5 w-5 rounded-full flex items-center justify-center">
                  {idx + 1}
                </span>
                <span className="text-sm font-semibold">{item}</span>
              </div>
            ))}
          </div>

          <button
            onClick={handleGenerateReport}
            disabled={isGenerating}
            className={`w-full py-4 px-6 bg-white text-gray-800 rounded-2xl font-bold flex items-center justify-center gap-2 shadow-xl hover:shadow-2xl transition-all hover:-translate-y-1 active:scale-95 ${isGenerating ? 'opacity-70 cursor-not-allowed' : ''}`}
          >
            {isGenerating ? (
              <i className="fas fa-circle-notch animate-spin"></i>
            ) : (
              <i className="fas fa-wand-magic-sparkles text-violet-600"></i>
            )}
            获取 AI 专家临床深度报告
          </button>
        </div>
      </div>

      {/* AI Report Modal/Section */}
      {aiReport && (
        <div className="w-full max-w-2xl mt-8 bg-white rounded-3xl p-8 shadow-lg border border-gray-100 animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-xl font-bold text-gray-800 flex items-center gap-2">
              <i className="fas fa-robot text-violet-500"></i>
              AI 专家深度报告
            </h3>
            <button onClick={() => setAiReport(null)} className="text-gray-400 hover:text-gray-600">
              <i className="fas fa-times"></i>
            </button>
          </div>
          <div className="prose prose-slate max-w-none text-gray-600 text-sm leading-relaxed whitespace-pre-wrap">
            {aiReport}
          </div>
          <div className="mt-8 p-4 bg-slate-50 rounded-2xl text-[10px] text-gray-400 text-center uppercase tracking-widest">
            报告由 Gemini 3 Pro AI 生成，仅供临床参考，决策请以主治医师意见为准
          </div>
        </div>
      )}

      {/* Footer Info */}
      <div className="mt-12 text-center text-gray-400 text-xs pb-8">
        <p>© 2024 PETS-LZRYEK 儿科急诊预检分诊决策工具</p>
        <p className="mt-1">依据《儿科急诊预检分诊专家共识（上海）》2022版构建</p>
      </div>
    </div>
  );
};

