              <h2 className="text-4xl font-black tracking-tight drop-shadow-sm">
                {currentTriage.levelName}
              </h2>
              {triageReason.length > 0 && (
                <div className="mt-4 flex flex-wrap gap-2">
                  {triageReason.map((reason, i) => (
                    <span key={i} className="text-[10px] bg-black/10 backdrop-blur-md px-2 py-1 rounded-lg font-bold border border-white/10">
                      {reason}
                    </span>
                  ))}
                </div>
              )}
            </div>
            <div className="bg-white/20 backdrop-blur-md px-5 py-3 rounded-2xl text-center border border-white/20">
              <div className="text-[9px] font-black opacity-80 mb-0.5 uppercase">响应时限</div>
              <div className="text-xl font-black leading-none">{currentTriage.responseTime}</div>
            </div>
          </div>

          <div className="bg-black/10 backdrop-blur-md rounded-2xl p-4 mb-6 border border-white/5">
            <p className="text-sm font-bold leading-relaxed">{currentTriage.description}</p>
          </div>

          <div className="space-y-2 mb-8">
            <div className="flex items-center gap-2 text-xs font-black opacity-90 mb-4 px-1">
