      { id: 'b1', name: '凝血功能障碍伴大出血', level: TriageLevel.L1 },
      { id: 'b2', name: '血小板 < 20x10^9/L 伴出血', level: TriageLevel.L2 },
      { id: 'b3', name: '血小板 < 20x10^9/L', level: TriageLevel.L3 },
      { id: 'b4', name: 'DKA (酮症酸中毒)', level: TriageLevel.L2 },
      { id: 'b5', name: '重度贫血', level: TriageLevel.L2 },
      { id: 'b6', name: '低血糖', level: TriageLevel.L2 },
