    ]
  },
  {
    id: 'other',
    name: '中毒/环境',
    symptoms: [
      { id: 'o1', name: '溺水 / 触电', level: TriageLevel.L1 },
      { id: 'o2', name: '严重中毒伴生命体征不稳定', level: TriageLevel.L1 },
      { id: 'o3', name: '动物咬伤伴中毒症状', level: TriageLevel.L2 },
