import React, { useState, useMemo } from 'react';
import { TRIAGE_CATEGORIES, TRIAGE_RESULT_CONFIG, HIGH_RISK_FACTORS } from './constants';
import { TriageLevel, PatientState, TriageResult, VitalSigns, Symptom } from './types';
import { getAIClinicalReport } from './services/geminiService';

const App: React.FC = () => {
  const [patient, setPatient] = useState<PatientState>({
    ageYears: '',
    ageMonths: '',
    ageDays: '',
    weight: '',
    vitals: {
      temperature: '',
      heartRate: '',
      respRate: '',
      bloodPressure: '',
      spo2: '',
      crt: '',
    },
    selectedSymptoms: new Set(),
    highRiskFactors: new Set(),
  });
  const [activeTab, setActiveTab] = useState(TRIAGE_CATEGORIES[0].id);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [confirmingSymptom, setConfirmingSymptom] = useState<Symptom | null>(null);

  const handleAgeChange = (field: keyof Pick<PatientState, 'ageYears' | 'ageMonths' | 'ageDays'>, value: string) => {
    if (value !== '' && !/^\d+$/.test(value)) return;
    setPatient(prev => ({ ...prev, [field]: value }));
  };

  const handleWeightChange = (value: string) => {
    if (value !== '' && !/^\d*\.?\d*$/.test(value)) return;
    setPatient(prev => ({ ...prev, weight: value }));
  };

  const handleVitalChange = (field: keyof VitalSigns, value: string) => {
    if (value !== '' && !/^\d*\.?\d*$/.test(value)) return;
    setPatient(prev => ({
      ...prev,
      vitals: { ...prev.vitals, [field]: value }
    }));
  };

  const toggleSymptom = (symptom: Symptom) => {
    if (patient.selectedSymptoms.has(symptom.id)) {
      setPatient(prev => {
        const next = new Set(prev.selectedSymptoms);
        next.delete(symptom.id);
        return { ...prev, selectedSymptoms: next };
      });
      return;
    }

    if (symptom.helperInfo) {
      setConfirmingSymptom(symptom);
    } else {
      executeToggleSymptom(symptom.id);
    }
  };

  const executeToggleSymptom = (id: string) => {
    setPatient(prev => {
      const next = new Set(prev.selectedSymptoms);
      next.add(id);
      return { ...prev, selectedSymptoms: next };
    });
    setAiReport(null);
    setConfirmingSymptom(null);
  };

  const toggleHighRisk = (id: string) => {
    setPatient(prev => {
      const next = new Set(prev.highRiskFactors);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return { ...prev, highRiskFactors: next };
    });
    setAiReport(null);
  };

  const reset = () => {
    setPatient({
      ageYears: '',
      ageMonths: '',
      ageDays: '',
      weight: '',
      vitals: {
        temperature: '',
        heartRate: '',
        respRate: '',
        bloodPressure: '',
        spo2: '',
        crt: '',
      },
      selectedSymptoms: new Set(),
      highRiskFactors: new Set(),
    });
    setAiReport(null);
  };

  const triageReason = useMemo(() => {
    const reasons: string[] = [];

    const years = parseInt(patient.ageYears) || 0;
    const months = parseInt(patient.ageMonths) || 0;
    const days = parseInt(patient.ageDays) || 0;
    const totalMonths = (years * 12) + months;

    const t = parseFloat(patient.vitals.temperature);
    const hr = parseFloat(patient.vitals.heartRate);
    const rr = parseFloat(patient.vitals.respRate);
    const spo2 = parseFloat(patient.vitals.spo2);
    const crt = parseFloat(patient.vitals.crt);

    if (spo2 > 0) {
      if (spo2 < 90) reasons.push("SpO2 < 90% (1级)");
      else if (spo2 <= 94) reasons.push("SpO2 90-94% (2级)");
    }

    if (crt >= 3) reasons.push("CRT ≥ 3s (2级)");

    if (t > 0) {
      if (t >= 41 || t < 35) reasons.push("体温异常极值 (2级)");
      if (totalMonths < 3 && t >= 38) reasons.push("<3月龄患儿发热 (2级/注1)");
    }

    if (hr > 0 || rr > 0) {
      if (years === 0 && months === 0 && days <= 28) {
        if (hr > 180 || hr < 100) reasons.push("新生儿心率异常 (2级)");
        if (rr > 60 || rr < 30) reasons.push("新生儿呼吸异常 (2级)");
      } else if (totalMonths <= 12) {
        if (hr > 180 || hr < 80) reasons.push("婴儿心率异常 (2级)");
        if (rr > 50 || rr < 25) reasons.push("婴儿呼吸异常 (2级)");
      } else if (years <= 3) {
        if (hr > 160 || hr < 70) reasons.push("幼儿心率异常 (2级)");
        if (rr > 40 || rr < 20) reasons.push("幼儿呼吸异常 (2级)");
      } else if (years <= 6) {
        if (hr > 140 || hr < 60) reasons.push("学龄前心率异常 (2级)");
        if (rr > 30 || rr < 18) reasons.push("学龄前呼吸异常 (2级)");
      } else {
        if (hr > 120 || hr < 50) reasons.push("年长儿心率异常 (2级)");
        if (rr > 24 || rr < 12) reasons.push("年长儿呼吸异常 (2级)");
      }
    }

    if (years === 0 && months === 0 && days <= 1 && days > 0) {
      reasons.push("24小时内新生儿 (2级)");
    } else if (years === 0 && months < 3 && months >= 0) {
      reasons.push("<3月龄婴儿 (3级)");
    }

    // High Risk Factors
    patient.highRiskFactors.forEach(id => {
      const factor = HIGH_RISK_FACTORS.find(f => f.id === id);
      if (factor) {
        reasons.push(`${factor.name} (调节)`);
      }
    });

    return reasons;
  }, [patient]);

  const currentTriage = useMemo((): TriageResult => {
    let baseLevel = 5;

    // 1. Symptom Based
    patient.selectedSymptoms.forEach(id => {
      TRIAGE_CATEGORIES.forEach(cat => {
        const sym = cat.symptoms.find(s => s.id === id);
        if (sym) {
          baseLevel = Math.min(baseLevel, sym.level);
        }
      });
    });

    // 2. Vital Signs & Age
    const spo2 = parseFloat(patient.vitals.spo2);
    if (spo2 > 0 && spo2 < 90) baseLevel = Math.min(baseLevel, 1);
    if (triageReason.some(r => r.includes("(1级)"))) baseLevel = Math.min(baseLevel, 1);
    else if (triageReason.some(r => r.includes("(2级)"))) baseLevel = Math.min(baseLevel, 2);
    else if (triageReason.some(r => r.includes("(3级)"))) baseLevel = Math.min(baseLevel, 3);

    // 3. Apply Upgrades (Notes 2, 3, 4)
    const shouldUpgrade = Array.from(patient.highRiskFactors).some(id => {
      return HIGH_RISK_FACTORS.find(f => f.id === id)?.upgrade;
    });

    if (shouldUpgrade && baseLevel > 1) {
      baseLevel -= 1;
    }

    return TRIAGE_RESULT_CONFIG[baseLevel as TriageLevel];
  }, [patient, triageReason]);

  const handleGenerateReport = async () => {
    setIsGenerating(true);
    const selectedSymptomsList: string[] = [];
    TRIAGE_CATEGORIES.forEach(cat => {
      cat.symptoms.forEach(s => {
        if (patient.selectedSymptoms.has(s.id)) {
          selectedSymptomsList.push(s.name);
        }
      });
    });
    patient.highRiskFactors.forEach(id => {
      const f = HIGH_RISK_FACTORS.find(x => x.id === id);
      if (f) selectedSymptomsList.push(`[高危因子] ${f.name}`);
    });

    const report = await getAIClinicalReport(
      { years: patient.ageYears, months: patient.ageMonths, days: patient.ageDays },
      patient.weight,
      patient.vitals,
      selectedSymptomsList,
      currentTriage.levelName
    );
    setAiReport(report || "报告生成失败");
    setIsGenerating(false);
  };

  return (
    <div className="min-h-screen p-4 md:p-8 flex flex-col items-center">
      {/* Helper Confirm Modal */}
      {confirmingSymptom && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl border border-gray-100 overflow-hidden transform animate-in slide-in-from-bottom-4 duration-500">
            <div className="p-6 bg-slate-50 border-b border-gray-100 flex items-center gap-3">
              <div className="w-10 h-10 bg-rose-100 rounded-full flex items-center justify-center text-rose-600">
                <i className="fas fa-stethoscope"></i>
              </div>
              <div>
                <h3 className="text-lg font-black text-gray-800">分诊指标详细核对</h3>
                <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">Clinical Criteria Verification</p>
              </div>
            </div>
            <div className="p-8">
              <div className="mb-4">
                <span className="text-xs font-black text-violet-600 uppercase tracking-widest">正在确认症状</span>
                <div className="text-2xl font-black text-gray-800 mt-1">{confirmingSymptom.name}</div>
              </div>
              <div className="p-6 bg-violet-50 rounded-2xl border border-violet-100 mb-8">
                <div className="text-[10px] font-black text-violet-400 uppercase mb-2 flex items-center gap-2">
                  <i className="fas fa-book-medical"></i>
                  共识定义 (表3/表4参考指标)
                </div>
                <p className="text-sm font-bold text-violet-900 leading-relaxed italic">
                  “{confirmingSymptom.helperInfo}”
                </p>
              </div>
              <div className="flex gap-3">
                <button 
                  onClick={() => setConfirmingSymptom(null)}
                  className="flex-1 py-4 bg-gray-100 text-gray-500 rounded-2xl font-black text-sm hover:bg-gray-200 transition-colors"
                >
                  取消
                </button>
                <button 
                  onClick={() => executeToggleSymptom(confirmingSymptom.id)}
                  className="flex-[2] py-4 bg-violet-600 text-white rounded-2xl font-black text-sm shadow-lg shadow-violet-200 hover:bg-violet-700 transition-all hover:-translate-y-0.5"
                >
                  确认符合该指标
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <div className="w-full max-w-2xl text-center mb-8">
        <h1 className="text-3xl font-bold text-gray-800 tracking-tight">PETS-LZRYEK</h1>
        <p className="text-gray-500 mt-1 uppercase text-[10px] tracking-[0.2em] font-bold">Shanghai Pediatric Triage Consensus 2022</p>
      </div>

      <div className="w-full max-w-2xl bg-white rounded-3xl shadow-xl overflow-hidden border border-gray-100 flex flex-col">
        {/* Patient Info Section */}
        <div className="p-6 bg-slate-50/50 border-b border-gray-100">
          <div className="flex justify-between items-center mb-4">
            <span className="text-sm font-bold text-gray-400 uppercase tracking-wider">患者基础信息录入</span>
            <button onClick={reset} className="text-rose-500 hover:bg-rose-50 p-2 rounded-full transition-colors">
              <i className="fas fa-rotate-left"></i>
            </button>
          </div>

          <div className="grid grid-cols-4 gap-3 mb-6">
            <div className="relative group">
              <label className="block text-[10px] text-gray-400 mb-1 ml-1 font-bold">岁</label>
              <input type="text" value={patient.ageYears} onChange={(e) => handleAgeChange('ageYears', e.target.value)} placeholder="--" className="w-full bg-white border border-gray-200 rounded-2xl py-2 px-3 text-center text-lg font-medium focus:ring-2 focus:ring-violet-500 focus:border-transparent outline-none" />
            </div>
            <div className="relative group">
              <label className="block text-[10px] text-gray-400 mb-1 ml-1 font-bold">月</label>
              <input type="text" value={patient.ageMonths} onChange={(e) => handleAgeChange('ageMonths', e.target.value)} placeholder="--" className="w-full bg-white border border-gray-200 rounded-2xl py-2 px-3 text-center text-lg font-medium focus:ring-2 focus:ring-violet-500 focus:border-transparent outline-none" />
            </div>
            <div className="relative group">
              <label className="block text-[10px] text-gray-400 mb-1 ml-1 font-bold">天</label>
              <input type="text" value={patient.ageDays} onChange={(e) => handleAgeChange('ageDays', e.target.value)} placeholder="--" className="w-full bg-white border border-gray-200 rounded-2xl py-2 px-3 text-center text-lg font-medium focus:ring-2 focus:ring-violet-500 focus:border-transparent outline-none" />
            </div>
            <div className="relative group">
              <label className="block text-[10px] text-gray-400 mb-1 ml-1 font-bold">体重(kg)</label>
              <input type="text" value={patient.weight} onChange={(e) => handleWeightChange(e.target.value)} placeholder="--" className="w-full bg-white border border-gray-200 rounded-2xl py-2 px-3 text-center text-lg font-medium focus:ring-2 focus:ring-amber-500 focus:border-transparent outline-none" />
            </div>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
            {[
              { id: 'temperature', label: '体温', unit: '°C', color: 'focus:ring-orange-400' },
              { id: 'heartRate', label: '心率', unit: '次/分', color: 'focus:ring-rose-400' },
              { id: 'respRate', label: '呼吸', unit: '次/分', color: 'focus:ring-blue-400' },
              { id: 'bloodPressure', label: '血压', unit: 'mmHg', color: 'focus:ring-indigo-400' },
              { id: 'spo2', label: 'SpO2', unit: '%', color: 'focus:ring-cyan-400' },
              { id: 'crt', label: 'CRT', unit: '秒', color: 'focus:ring-emerald-400' },
            ].map((vital) => (
              <div key={vital.id} className="relative">
                <label className="block text-[10px] text-gray-400 mb-1 ml-1 font-bold uppercase">{vital.label}</label>
                <div className="relative">
                  <input type="text" value={patient.vitals[vital.id as keyof VitalSigns]} onChange={(e) => handleVitalChange(vital.id as keyof VitalSigns, e.target.value)} placeholder="--" className={`w-full bg-white border border-gray-200 rounded-xl py-2 px-3 text-center text-sm font-semibold focus:ring-2 ${vital.color} focus:border-transparent outline-none transition-all`} />
                  <span className="absolute right-2 bottom-2 text-[8px] text-gray-300 pointer-events-none">{vital.unit}</span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* High Risk Notes Section (Adjusting Factors) */}
        <div className="p-4 bg-amber-50/50 border-b border-amber-100">
          <div className="text-[10px] font-bold text-amber-600 uppercase mb-3 px-2 flex items-center gap-1">
            <i className="fas fa-exclamation-triangle"></i>
            共识决策“注”项确认 (调节分级)
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
            {HIGH_RISK_FACTORS.map(f => (
              <button
                key={f.id}
                onClick={() => toggleHighRisk(f.id)}
                className={`p-3 rounded-xl border text-xs text-left transition-all flex items-center gap-3 ${
                  patient.highRiskFactors.has(f.id)
                    ? 'bg-amber-100 border-amber-300 text-amber-800 font-bold'
                    : 'bg-white border-gray-100 text-gray-500'
                }`}
              >
                <div className={`w-4 h-4 rounded-md border flex items-center justify-center ${patient.highRiskFactors.has(f.id) ? 'bg-amber-500 border-amber-500' : 'bg-white border-gray-300'}`}>
                  {patient.highRiskFactors.has(f.id) && <i className="fas fa-check text-white text-[8px]"></i>}
                </div>
                {f.name}
              </button>
            ))}
          </div>
        </div>

        {/* Category Tabs */}
        <div className="p-4 grid grid-cols-2 md:grid-cols-4 gap-2 bg-slate-50/30">
          {TRIAGE_CATEGORIES.map(cat => (
            <button
              key={cat.id}
              onClick={() => setActiveTab(cat.id)}
              className={`py-2 px-3 rounded-xl text-xs font-semibold transition-all ${
                activeTab === cat.id
                  ? 'bg-violet-600 text-white shadow-lg shadow-violet-200'
                  : 'bg-white text-gray-500 border border-gray-100 hover:bg-gray-50'
              }`}
            >
              {cat.name}
            </button>
          ))}
        </div>

        {/* Symptoms List */}
        <div className="p-6 flex-1 min-h-[300px] max-h-[400px] overflow-y-auto custom-scrollbar">
          <div className="space-y-2">
