            <div className="bg-white/20 backdrop-blur-md px-5 py-3 rounded-2xl text-center border border-white/20">
              <div className="text-[9px] font-black opacity-80 mb-0.5 uppercase">响应时限</div>
              <div className="text-xl font-black leading-none">{currentTriage.responseTime}</div>
            </div>
          </div>

          <div className="bg-black/10 backdrop-blur-md rounded-2xl p-4 mb-6 border border-white/5">
            <p className="text-sm font-bold leading-relaxed">{currentTriage.description}</p>
          </div>

          <div className="space-y-2 mb-8">
            <div className="flex items-center gap-2 text-xs font-black opacity-90 mb-4 px-1">
              <i className="fas fa-hand-holding-medical"></i>
              <span className="uppercase tracking-widest">临床预检干预要点</span>
            </div>
            {currentTriage.interventions.map((item, idx) => (
              <div key={idx} className="flex items-center gap-4 bg-white/15 backdrop-blur-md p-4 rounded-2xl border border-white/10 shadow-sm">
                <span className="bg-white text-gray-800 text-[10px] font-black h-6 w-6 rounded-full flex items-center justify-center shrink-0">
                  {idx + 1}
                </span>
                <span className="text-sm font-bold tracking-wide">{item}</span>
              </div>
            ))}
          </div>

          <button
            onClick={handleGenerateReport}
            disabled={isGenerating}
            className={`w-full py-5 px-6 bg-white text-gray-900 rounded-3xl font-black flex items-center justify-center gap-3 shadow-2xl hover:shadow-white/20 transition-all hover:-translate-y-1 active:scale-95 border-b-4 border-gray-200 ${isGenerating ? 'opacity-70 cursor-not-allowed' : ''}`}
          >
            {isGenerating ? (
              <i className="fas fa-circle-notch animate-spin"></i>
            ) : (
              <i className="fas fa-brain text-violet-600"></i>
            )}
            获取 2.5 Pro AI 专家临床决策报告
          </button>
        </div>
      </div>

      {/* AI Report */}
      {aiReport && (
        <div className="w-full max-w-2xl mt-8 bg-white rounded-[2.5rem] p-10 shadow-2xl border border-gray-100 animate-in fade-in slide-in-from-bottom-6 duration-700">
