            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-violet-100 rounded-2xl flex items-center justify-center">
                <i className="fas fa-microchip text-violet-600 text-xl"></i>
              </div>
              <div>
                <h3 className="text-xl font-black text-gray-800 tracking-tight">AI 临床分析</h3>
                <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Expert Clinical Reasoning</p>
              </div>
            </div>
            <button onClick={() => setAiReport(null)} className="w-10 h-10 rounded-full hover:bg-gray-100 flex items-center justify-center transition-colors">
              <i className="fas fa-times text-gray-400"></i>
            </button>
          </div>
          <div className="prose prose-slate max-w-none text-gray-700 text-sm leading-relaxed whitespace-pre-wrap font-medium">
            {aiReport}
          </div>
          <div className="mt-10 p-5 bg-slate-50 rounded-2xl text-[9px] text-gray-400 text-center font-bold border border-slate-100 uppercase tracking-widest leading-loose">
            报告由集成 Gemini 2.5 Pro 模型生成，包含调节因子推演，<br/>
            仅供临床参考，最终决策需经高年资急诊医师确认。
          </div>
        </div>
      )}

      {/* Footer */}
      <div className="mt-16 text-center text-gray-400 text-[10px] font-bold pb-12 tracking-widest uppercase">
        <p>© PETS-LZRYEK · 2024</p>
        <p className="mt-2 text-gray-300">Pediatric Emergency Triage Standard · Shanghai Consensus</p>
      </div>
    </div>
  );
};

