              <i className="fas fa-shield-check"></i>
              Clinical Disclaimer
            </div>
            <p className="text-[10px] text-slate-400 font-bold leading-relaxed uppercase">
              本报告由 Gemini 2.5 Pro 基于《儿科急诊预检分诊专家共识（上海）》推理生成。包含 GPRCV 深度指标评估与调节因子计算。
              所有 AI 建议仅供辅助决策，最终处分与医疗行为必须由具备执业资格的主治医师完成。
            </p>
          </div>
        </div>
      )}

      {/* Site Footer */}
      <div className="mt-20 text-center pb-16">
        <p className="text-[11px] font-black text-slate-300 uppercase tracking-[0.5em]">PETS-LZRYEK · System v2.0</p>
        <p className="mt-3 text-[9px] font-bold text-slate-400 uppercase tracking-widest opacity-60">LZRYEK Children's Hospital Emergency Triage Standard</p>
      </div>
    </div>
  );
};

