import React, { useState, useMemo } from 'react';
import { TRIAGE_CATEGORIES, TRIAGE_RESULT_CONFIG, HIGH_RISK_FACTORS } from './constants';
import { TriageLevel, PatientState, TriageResult, VitalSigns, Symptom } from './types';
import { getAIClinicalReport } from './services/geminiService';

const App: React.FC = () => {
  const [patient, setPatient] = useState<PatientState>({
    ageYears: '',
    ageMonths: '',
    ageDays: '',
    weight: '',
    vitals: {
      temperature: '',
      heartRate: '',
      respRate: '',
      bloodPressure: '',
      spo2: '',
      crt: '',
    },
    selectedSymptoms: new Set(),
    highRiskFactors: new Set(),
  });
  const [activeTab, setActiveTab] = useState(TRIAGE_CATEGORIES[0].id);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [confirmingSymptom, setConfirmingSymptom] = useState<Symptom | null>(null);

  const handleAgeChange = (field: keyof Pick<PatientState, 'ageYears' | 'ageMonths' | 'ageDays'>, value: string) => {
    if (value !== '' && !/^\d+$/.test(value)) return;
    setPatient(prev => ({ ...prev, [field]: value }));
  };

  const handleWeightChange = (value: string) => {
    if (value !== '' && !/^\d*\.?\d*$/.test(value)) return;
    setPatient(prev => ({ ...prev, weight: value }));
  };

  const handleVitalChange = (field: keyof VitalSigns, value: string) => {
    if (value !== '' && !/^\d*\.?\d*$/.test(value)) return;
    setPatient(prev => ({
      ...prev,
      vitals: { ...prev.vitals, [field]: value }
    }));
  };

  const toggleSymptom = (symptom: Symptom) => {
    if (patient.selectedSymptoms.has(symptom.id)) {
      setPatient(prev => {
        const next = new Set(prev.selectedSymptoms);
        next.delete(symptom.id);
        return { ...prev, selectedSymptoms: next };
      });
      return;
    }

    if (symptom.helperInfo) {
      setConfirmingSymptom(symptom);
    } else {
      executeToggleSymptom(symptom.id);
    }
  };

  const executeToggleSymptom = (id: string) => {
    setPatient(prev => {
      const next = new Set(prev.selectedSymptoms);
      next.add(id);
      return { ...prev, selectedSymptoms: next };
    });
    setAiReport(null);
    setConfirmingSymptom(null);
  };

  const toggleHighRisk = (id: string) => {
    setPatient(prev => {
      const next = new Set(prev.highRiskFactors);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return { ...prev, highRiskFactors: next };
    });
    setAiReport(null);
  };

  const reset = () => {
    setPatient({
      ageYears: '',
      ageMonths: '',
      ageDays: '',
      weight: '',
      vitals: {
        temperature: '',
        heartRate: '',
        respRate: '',
        bloodPressure: '',
        spo2: '',
        crt: '',
      },
      selectedSymptoms: new Set(),
      highRiskFactors: new Set(),
    });
    setAiReport(null);
  };

  const triageReason = useMemo(() => {
    const reasons: string[] = [];

    const years = parseInt(patient.ageYears) || 0;
    const months = parseInt(patient.ageMonths) || 0;
    const days = parseInt(patient.ageDays) || 0;
    const totalMonths = (years * 12) + months;

    const t = parseFloat(patient.vitals.temperature);
    const hr = parseFloat(patient.vitals.heartRate);
    const rr = parseFloat(patient.vitals.respRate);
    const spo2 = parseFloat(patient.vitals.spo2);
    const crt = parseFloat(patient.vitals.crt);
    const sbp = parseFloat(patient.vitals.bloodPressure);

    // V: Vital Signs Logic
    if (spo2 > 0) {
      if (spo2 < 90) reasons.push("V: SpO2 < 90% (1级)");
      else if (spo2 <= 94) reasons.push("V: SpO2 90-94% (2级)");
    }

    if (crt >= 3) {
      if (crt > 5) reasons.push("C: CRT > 5s (1级)");
      else reasons.push("C: CRT 3-5s (2级)");
    }

    // C: BP Formula Logic
    if (sbp > 0) {
      let isHypotension = false;
      if (years === 0 && months === 0 && days <= 28 && sbp < 60) isHypotension = true;
      else if (totalMonths <= 12 && sbp < 70) isHypotension = true;
      else if (years >= 1 && years <= 10 && sbp < (70 + years * 2)) isHypotension = true;
      else if (years > 10 && sbp < 90) isHypotension = true;

      if (isHypotension) reasons.push("C: 低血压 (1级)");
    }

    if (t > 0) {
      if (t >= 41 || t < 35) reasons.push("V: 体温极值 (2级)");
      if (totalMonths < 3 && t >= 38) reasons.push("V: <3月龄发热 (2级)");
    }

    // Symptom-specific reasons
    patient.selectedSymptoms.forEach(id => {
      TRIAGE_CATEGORIES.forEach(cat => {
        const sym = cat.symptoms.find(s => s.id === id);
        if (sym) reasons.push(`${sym.name}`);
      });
    });

    patient.highRiskFactors.forEach(id => {
      const factor = HIGH_RISK_FACTORS.find(f => f.id === id);
      if (factor) reasons.push(`${factor.name} (调节)`);
    });

    return reasons;
  }, [patient]);

  const currentTriage = useMemo((): TriageResult => {
    let baseLevel = 5;

    // 1. Symptom Based
    patient.selectedSymptoms.forEach(id => {
      TRIAGE_CATEGORIES.forEach(cat => {
        const sym = cat.symptoms.find(s => s.id === id);
        if (sym) baseLevel = Math.min(baseLevel, sym.level);
      });
    });

    // 2. Vital Signs Logic Check
    if (triageReason.some(r => r.includes("(1级)"))) baseLevel = Math.min(baseLevel, 1);
    else if (triageReason.some(r => r.includes("(2级)"))) baseLevel = Math.min(baseLevel, 2);

    // 3. High Risk Factor Upgrade
    const shouldUpgrade = Array.from(patient.highRiskFactors).some(id => {
      return HIGH_RISK_FACTORS.find(f => f.id === id)?.upgrade;
    });

    if (shouldUpgrade && baseLevel > 1) {
      baseLevel -= 1;
    }

    return TRIAGE_RESULT_CONFIG[baseLevel as TriageLevel];
  }, [patient, triageReason]);

  const handleGenerateReport = async () => {
    setIsGenerating(true);
    const symptomsList: string[] = [];
    TRIAGE_CATEGORIES.forEach(cat => {
      cat.symptoms.forEach(s => {
        if (patient.selectedSymptoms.has(s.id)) symptomsList.push(s.name);
      });
    });
    patient.highRiskFactors.forEach(id => {
      const f = HIGH_RISK_FACTORS.find(x => x.id === id);
      if (f) symptomsList.push(`[风险调节] ${f.name}`);
    });

    const report = await getAIClinicalReport(
      { years: patient.ageYears, months: patient.ageMonths, days: patient.ageDays },
      patient.weight,
      patient.vitals,
      symptomsList,
      currentTriage.levelName
    );
    setAiReport(report || "报告生成失败");
    setIsGenerating(false);
  };

  return (
    <div className="min-h-screen p-4 md:p-8 flex flex-col items-center">
      {/* Confirmation Modal */}
      {confirmingSymptom && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white rounded-[2rem] w-full max-w-lg shadow-2xl border-4 border-indigo-600/10 overflow-hidden transform animate-in zoom-in-95 duration-300">
            <div className="p-8 bg-indigo-600 text-white flex items-center gap-4">
              <div className="w-14 h-14 bg-white/20 rounded-2xl flex items-center justify-center">
                <i className="fas fa-microscope text-2xl"></i>
              </div>
              <div>
                <h3 className="text-xl font-black tracking-tight">临床标准核对</h3>
                <p className="text-[10px] font-bold uppercase tracking-[0.2em] opacity-80">Consensus Verification</p>
              </div>
            </div>
            <div className="p-8">
              <div className="mb-6">
                <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest bg-indigo-50 px-3 py-1.5 rounded-full">
                  当前评估项: {confirmingSymptom.name}
                </span>
              </div>
              <div className="p-6 bg-slate-50 rounded-2xl border-2 border-slate-100 mb-10">
                <div className="text-[10px] font-black text-slate-400 uppercase mb-3 flex items-center gap-2">
                  <i className="fas fa-file-contract text-indigo-400"></i>
                  《上海共识》判定标准
                </div>
                <p className="text-sm font-black text-slate-700 leading-loose whitespace-pre-wrap">
                  {confirmingSymptom.helperInfo}
                </p>
              </div>
              <div className="flex gap-4">
                <button 
                  onClick={() => setConfirmingSymptom(null)}
                  className="flex-1 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black text-sm hover:bg-slate-200 transition-all active:scale-95"
                >
                  不符合
                </button>
                <button 
                  onClick={() => executeToggleSymptom(confirmingSymptom.id)}
                  className="flex-[2] py-5 bg-indigo-600 text-white rounded-2xl font-black text-sm shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95"
                >
                  确认符合
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <div className="w-full max-w-3xl text-center mb-10">
        <h1 className="text-4xl font-black text-slate-900 tracking-tighter">PETS-LZRYEK</h1>
        <div className="flex items-center justify-center gap-3 mt-3">
          <span className="px-3 py-1 bg-indigo-600 text-white text-[10px] font-black rounded-lg uppercase tracking-widest shadow-lg shadow-indigo-100">
            Smart Triage
          </span>
          <span className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.3em]">Shanghai Consensus Protocol</span>
        </div>
      </div>

      <div className="w-full max-w-3xl bg-white rounded-[3rem] shadow-2xl shadow-slate-200/60 overflow-hidden border border-slate-100 flex flex-col">
        {/* Vital Input Section */}
        <div className="p-10 bg-slate-50/50 border-b border-slate-100">
          <div className="flex justify-between items-center mb-8">
            <div className="flex items-center gap-3">
              <div className="w-2 h-8 bg-indigo-600 rounded-full"></div>
              <span className="text-sm font-black text-slate-800 uppercase tracking-widest">患者基础特征 & V-生命体征</span>
            </div>
            <button onClick={reset} className="text-rose-500 hover:bg-rose-50 h-12 w-12 flex items-center justify-center rounded-2xl transition-all shadow-sm border border-rose-100">
              <i className="fas fa-rotate-left"></i>
            </button>
          </div>

          <div className="grid grid-cols-4 gap-5 mb-10">
            {['ageYears', 'ageMonths', 'ageDays', 'weight'].map((key) => (
              <div key={key} className="relative group">
                <label className="block text-[10px] text-slate-400 mb-2 ml-1 font-black uppercase tracking-widest">
                  {key === 'ageYears' ? '岁' : key === 'ageMonths' ? '月' : key === 'ageDays' ? '天' : '体重(kg)'}
                </label>
                <input
                  type="text"
                  value={(patient as any)[key]}
                  onChange={(e) => key === 'weight' ? handleWeightChange(e.target.value) : handleAgeChange(key as any, e.target.value)}
                  placeholder="--"
                  className="w-full bg-white border-2 border-slate-100 rounded-2xl py-4 px-3 text-center text-2xl font-black text-slate-800 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-50 outline-none transition-all"
                />
              </div>
            ))}
          </div>

          <div className="grid grid-cols-2 md:grid-cols-3 gap-5">
            {[
              { id: 'temperature', label: 'T (体温)', unit: '°C', color: 'focus:border-orange-400' },
              { id: 'heartRate', label: 'HR (心率)', unit: '次/分', color: 'focus:border-rose-400' },
              { id: 'respRate', label: 'RR (呼吸)', unit: '次/分', color: 'focus:border-blue-400' },
              { id: 'bloodPressure', label: 'BP (收缩压)', unit: 'mmHg', color: 'focus:border-indigo-400' },
              { id: 'spo2', label: 'SpO2 (血氧)', unit: '%', color: 'focus:border-cyan-400' },
              { id: 'crt', label: 'CRT (毛充)', unit: '秒', color: 'focus:border-emerald-400' },
            ].map((vital) => (
              <div key={vital.id} className="relative">
                <label className="block text-[10px] text-slate-400 mb-2 ml-1 font-black uppercase tracking-widest">{vital.label}</label>
                <div className="relative">
                  <input
                    type="text"
                    value={patient.vitals[vital.id as keyof VitalSigns]}
                    onChange={(e) => handleVitalChange(vital.id as keyof VitalSigns, e.target.value)}
                    placeholder="--"
                    className={`w-full bg-white border-2 border-slate-100 rounded-2xl py-3 px-3 text-center text-lg font-black text-slate-700 focus:ring-8 focus:ring-slate-100 transition-all ${vital.color}`}
                  />
                  <span className="absolute right-4 bottom-3 text-[9px] text-slate-300 font-black uppercase tracking-tighter">{vital.unit}</span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Adjusting Factors (Notes) */}
        <div className="px-10 py-6 bg-amber-50/40 border-b border-amber-100/50">
          <div className="text-[10px] font-black text-amber-600 uppercase mb-5 flex items-center gap-3 tracking-[0.25em]">
            <i className="fas fa-sliders-h"></i>
            共识调节因素 (P-疼痛与高危因子)
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {HIGH_RISK_FACTORS.map(f => (
              <button
                key={f.id}
                onClick={() => f.helperInfo ? setConfirmingSymptom(f as any) : toggleHighRisk(f.id)}
                className={`p-4 rounded-2xl border-2 text-[11px] text-left transition-all flex items-start gap-4 ${
                  patient.highRiskFactors.has(f.id)
                    ? 'bg-amber-100 border-amber-300 text-amber-900 font-black'
                    : 'bg-white border-slate-100 text-slate-500'
                }`}
              >
                <div className={`mt-0.5 w-5 h-5 rounded-lg border-2 shrink-0 flex items-center justify-center ${patient.highRiskFactors.has(f.id) ? 'bg-amber-600 border-amber-600' : 'bg-slate-200 border-slate-200'}`}>
                  {patient.highRiskFactors.has(f.id) && <i className="fas fa-check text-white text-[9px]"></i>}
                </div>
                <span>{f.name}</span>
              </button>
            ))}
          </div>
        </div>

        {/* System Navigation Tabs */}
        <div className="p-6 flex gap-3 overflow-x-auto no-scrollbar bg-slate-50/20 border-b border-slate-100">
          {TRIAGE_CATEGORIES.map(cat => (
            <button
              key={cat.id}
              onClick={() => setActiveTab(cat.id)}
              className={`whitespace-nowrap px-6 py-4 rounded-2xl text-[11px] font-black transition-all border-2 ${
                activeTab === cat.id
                  ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl shadow-indigo-100'
                  : 'bg-white border-slate-100 text-slate-400 hover:border-slate-200'
              }`}
            >
              {cat.name}
            </button>
          ))}
        </div>

        {/* Symptoms Grid */}
        <div className="p-10 flex-1 min-h-[400px] max-h-[500px] overflow-y-auto custom-scrollbar bg-white">
          <div className="grid grid-cols-1 gap-4">
            {TRIAGE_CATEGORIES.find(c => c.id === activeTab)?.symptoms.map(sym => (
              <button
                key={sym.id}
                onClick={() => toggleSymptom(sym)}
                className={`group w-full text-left p-6 rounded-[2rem] border-2 transition-all flex items-center justify-between ${
                  patient.selectedSymptoms.has(sym.id)
                    ? 'border-indigo-600 bg-indigo-50/50'
                    : 'border-slate-50 bg-slate-50/20 hover:border-indigo-100 shadow-sm'
                }`}
              >
                <div className="flex flex-col gap-1">
                  <span className={`text-base font-black tracking-tight ${patient.selectedSymptoms.has(sym.id) ? 'text-indigo-900' : 'text-slate-700'}`}>
                    {sym.name}
                  </span>
                  {sym.helperInfo && (
                    <span className="text-[10px] text-indigo-400 font-bold flex items-center gap-1.5 mt-1">
                      <i className="fas fa-clipboard-check"></i>
                      点击核对 GPRCV 临床判定标准
                    </span>
                  )}
                </div>
                <div className={`w-10 h-10 rounded-2xl flex items-center justify-center transition-all ${patient.selectedSymptoms.has(sym.id) ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-300 group-hover:bg-indigo-100 group-hover:text-indigo-500'}`}>
                  <i className={`fas ${patient.selectedSymptoms.has(sym.id) ? 'fa-check' : 'fa-plus-circle'} text-base`}></i>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Dynamic Triage Result */}
        <div className={`p-12 ${currentTriage.zoneColor} text-white transition-all duration-700 relative`}>
          <div className="flex justify-between items-start mb-12">
            <div className="flex-1">
              <div className="flex items-center gap-3 mb-5">
                <div className="px-4 py-1.5 bg-white/20 backdrop-blur-md rounded-full text-[10px] font-black uppercase tracking-[0.2em] border border-white/20">
                  <i className="fas fa-shield-alt mr-2"></i>
                  Auto Triage Decision
                </div>
              </div>
              <h2 className="text-6xl font-black tracking-tighter drop-shadow-2xl mb-6">
                {currentTriage.levelName}
              </h2>
              <div className="flex flex-wrap gap-2.5">
                {triageReason.length > 0 ? triageReason.map((reason, i) => (
                  <span key={i} className="px-4 py-2 bg-black/15 backdrop-blur-lg rounded-2xl text-[11px] font-black border border-white/10 flex items-center gap-2 shadow-sm">
                    <div className="w-1.5 h-1.5 bg-white rounded-full animate-pulse"></div>
                    {reason}
                  </span>
                )) : (
                  <span className="text-sm font-bold opacity-60 italic">无特异性指标触发，默认为 5 级</span>
                )}
              </div>
            </div>
            <div className="bg-white text-slate-900 p-8 rounded-[3rem] text-center shadow-2xl border-8 border-white/20 flex flex-col justify-center min-w-[140px]">
              <div className="text-[10px] font-black text-slate-400 mb-2 uppercase tracking-widest leading-none">Resp Limit</div>
              <div className="text-3xl font-black leading-none">{currentTriage.responseTime}</div>
            </div>
          </div>

          <div className="bg-white/10 backdrop-blur-xl rounded-[2.5rem] p-8 mb-12 border border-white/20 shadow-inner">
            <div className="flex items-center gap-3 mb-3 text-white/60 text-[10px] font-black uppercase tracking-widest">
              <i className="fas fa-stethoscope"></i>
