import { GoogleGenAI } from "@google/genai";
import { VitalSigns } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getAIClinicalReport = async (
  age: { years: string; months: string; days: string },
  weight: string,
  vitals: VitalSigns,
  selectedSymptoms: string[],
  triageLevel: string
) => {
  const prompt = `
    作为一名资深儿科急诊专家，请针对以下患儿情况提供一份深度的临床预检分析报告：

    患儿基本资料：
    - 年龄：${age.years}岁 ${age.months}月 ${age.days}天
    - 体重：${weight || '未录入'}kg
    - 生命体征：
      * 体温: ${vitals.temperature || '未录入'}°C
      * 心率: ${vitals.heartRate || '未录入'}次/分
      * 呼吸: ${vitals.respRate || '未录入'}次/分
      * 血压: ${vitals.bloodPressure || '未录入'}mmHg
      * SpO2: ${vitals.spo2 || '未录入'}%
      * CRT: ${vitals.crt || '未录入'}秒
    - 预检分级结果：${triageLevel}
    - 识别到的症状：${selectedSymptoms.join('、') || '无特异性症状'}

    请按以下结构输出：
    1. 【病情评估】 分析当前生命体征和症状的严重性及其在儿科急诊中的临床意义。
    2. 【潜在风险】 基于当前指标，列出可能出现的恶化指标或潜在并发症。
    3. 【临床路径建议】 建议的实验室检查及影像学检查。
    4. 【干预重点】 护理及首接医生应重点监测的生命体征。

    语言风格：专业、严谨、简洁。
    格式：使用Markdown。
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("AI Report generation failed:", error);
    return "暂时无法生成AI临床报告，请检查网络连接或API配置。";
  }
};

import React, { useState, useMemo } from 'react';
import { TRIAGE_CATEGORIES, TRIAGE_RESULT_CONFIG, HIGH_RISK_FACTORS } from './constants';
import { TriageLevel, PatientState, TriageResult, VitalSigns, Symptom } from './types';
import { getAIClinicalReport } from './services/geminiService';

const App: React.FC = () => {
  const [patient, setPatient] = useState<PatientState>({
    ageYears: '',
    ageMonths: '',
    ageDays: '',
    weight: '',
    vitals: {
      temperature: '',
      heartRate: '',
      respRate: '',
      bloodPressure: '',
      spo2: '',
      crt: '',
    },
    selectedSymptoms: new Set(),
    highRiskFactors: new Set(),
  });
  const [activeTab, setActiveTab] = useState(TRIAGE_CATEGORIES[0].id);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [confirmingSymptom, setConfirmingSymptom] = useState<Symptom | null>(null);

  const handleAgeChange = (field: keyof Pick<PatientState, 'ageYears' | 'ageMonths' | 'ageDays'>, value: string) => {
    if (value !== '' && !/^\d+$/.test(value)) return;
    setPatient(prev => ({ ...prev, [field]: value }));
  };

  const handleWeightChange = (value: string) => {
    if (value !== '' && !/^\d*\.?\d*$/.test(value)) return;
    setPatient(prev => ({ ...prev, weight: value }));
  };

  const handleVitalChange = (field: keyof VitalSigns, value: string) => {
    if (value !== '' && !/^\d*\.?\d*$/.test(value)) return;
    setPatient(prev => ({
      ...prev,
      vitals: { ...prev.vitals, [field]: value }
    }));
  };

  const toggleSymptom = (symptom: Symptom) => {
    if (patient.selectedSymptoms.has(symptom.id)) {
      setPatient(prev => {
        const next = new Set(prev.selectedSymptoms);
        next.delete(symptom.id);
        return { ...prev, selectedSymptoms: next };
      });
      return;
    }

    if (symptom.helperInfo) {
      setConfirmingSymptom(symptom);
    } else {
      executeToggleSymptom(symptom.id);
    }
  };

  const executeToggleSymptom = (id: string) => {
    setPatient(prev => {
      const next = new Set(prev.selectedSymptoms);
      next.add(id);
      return { ...prev, selectedSymptoms: next };
    });
    setAiReport(null);
    setConfirmingSymptom(null);
  };

  const toggleHighRisk = (id: string) => {
    setPatient(prev => {
      const next = new Set(prev.highRiskFactors);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return { ...prev, highRiskFactors: next };
    });
    setAiReport(null);
  };

  const reset = () => {
    setPatient({
      ageYears: '',
      ageMonths: '',
      ageDays: '',
      weight: '',
      vitals: {
        temperature: '',
        heartRate: '',
        respRate: '',
        bloodPressure: '',
        spo2: '',
        crt: '',
      },
      selectedSymptoms: new Set(),
      highRiskFactors: new Set(),
    });
    setAiReport(null);
  };

  const triageReason = useMemo(() => {
    const reasons: string[] = [];
    const years = parseInt(patient.ageYears) || 0;
    const months = parseInt(patient.ageMonths) || 0;
    const days = parseInt(patient.ageDays) || 0;
    const totalMonths = (years * 12) + months;

    const t = parseFloat(patient.vitals.temperature);
    const spo2 = parseFloat(patient.vitals.spo2);
    const crt = parseFloat(patient.vitals.crt);
    const sbp = parseFloat(patient.vitals.bloodPressure);

    if (spo2 > 0) {
      if (spo2 < 90) reasons.push("V: SpO2 < 90% (1级)");
      else if (spo2 <= 94) reasons.push("V: SpO2 90-94% (2级)");
    }

    if (crt >= 3) {
      if (crt > 5) reasons.push("C: CRT > 5s (1级)");
      else reasons.push("C: CRT 3-5s (2级)");
    }

    if (sbp > 0) {
      let isHypotension = false;
      if (years === 0 && months === 0 && days <= 28 && sbp < 60) isHypotension = true;
      else if (totalMonths <= 12 && sbp < 70) isHypotension = true;
      else if (years >= 1 && years <= 10 && sbp < (70 + years * 2)) isHypotension = true;
      else if (years > 10 && sbp < 90) isHypotension = true;
      if (isHypotension) reasons.push("C: 低血压 (1级)");
    }

    if (t > 0) {
      if (t >= 41 || t < 35) reasons.push("V: 体温极值 (2级)");
      if (totalMonths < 3 && t >= 38) reasons.push("V: <3月龄发热 (2级)");
    }

    patient.selectedSymptoms.forEach(id => {
      TRIAGE_CATEGORIES.forEach(cat => {
        const sym = cat.symptoms.find(s => s.id === id);
        if (sym) reasons.push(`${sym.name}`);
      });
    });

    patient.highRiskFactors.forEach(id => {
      const factor = HIGH_RISK_FACTORS.find(f => f.id === id);
      if (factor) reasons.push(`${factor.name}`);
    });

    return reasons;
  }, [patient]);

  const currentTriage = useMemo((): TriageResult => {
    let baseLevel = 5;
    patient.selectedSymptoms.forEach(id => {
      TRIAGE_CATEGORIES.forEach(cat => {
        const sym = cat.symptoms.find(s => s.id === id);
        if (sym) baseLevel = Math.min(baseLevel, sym.level);
      });
    });
    if (triageReason.some(r => r.includes("(1级)"))) baseLevel = Math.min(baseLevel, 1);
    else if (triageReason.some(r => r.includes("(2级)"))) baseLevel = Math.min(baseLevel, 2);

    const shouldUpgrade = Array.from(patient.highRiskFactors).some(id => {
      return HIGH_RISK_FACTORS.find(f => f.id === id)?.upgrade;
    });
    if (shouldUpgrade && baseLevel > 1) baseLevel -= 1;

    return TRIAGE_RESULT_CONFIG[baseLevel as TriageLevel];
  }, [patient, triageReason]);

  const handleGenerateReport = async () => {
    setIsGenerating(true);
    const symptomsList: string[] = [];
    TRIAGE_CATEGORIES.forEach(cat => {
      cat.symptoms.forEach(s => { if (patient.selectedSymptoms.has(s.id)) symptomsList.push(s.name); });
    });
    patient.highRiskFactors.forEach(id => {
      const f = HIGH_RISK_FACTORS.find(x => x.id === id);
      if (f) symptomsList.push(`[风险因子] ${f.name}`);
    });
    const report = await getAIClinicalReport(
      { years: patient.ageYears, months: patient.ageMonths, days: patient.ageDays },
      patient.weight, patient.vitals, symptomsList, currentTriage.levelName
    );
    setAiReport(report || "报告生成失败");
    setIsGenerating(false);
    setTimeout(() => { window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' }); }, 100);
  };

  return (
    <div className="min-h-screen p-4 md:p-8 flex flex-col items-center max-w-5xl mx-auto">
      {/* Confirmation Modal */}
      {confirmingSymptom && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl w-full max-w-md shadow-2xl overflow-hidden transform animate-in zoom-in-95 duration-200">
            <div className="p-6 bg-indigo-600 text-white flex items-center gap-3">
              <i className="fas fa-stethoscope text-xl"></i>
              <h3 className="font-black">判定标准核对</h3>
            </div>
            <div className="p-6">
              <p className="text-sm font-black text-slate-800 mb-4">{confirmingSymptom.name}</p>
              <div className="p-4 bg-slate-50 rounded-xl border border-slate-100 mb-6 text-xs font-bold text-slate-600 leading-relaxed">
                {confirmingSymptom.helperInfo}
              </div>
              <div className="flex gap-3">
                <button onClick={() => setConfirmingSymptom(null)} className="flex-1 py-3 bg-slate-100 text-slate-500 rounded-xl font-bold">不符合</button>
                <button onClick={() => executeToggleSymptom(confirmingSymptom.id)} className="flex-[2] py-3 bg-indigo-600 text-white rounded-xl font-bold">符合</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <div className="text-center mb-8">
        <h1 className="text-3xl font-black text-slate-900 tracking-tighter">PETS-LZRYEK</h1>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">儿科急诊预检分诊决策工具</p>
      </div>

      <div className="w-full grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        {/* Left: Input Areas */}
        <div className="lg:col-span-7 space-y-6">
          <div className="bg-white rounded-3xl shadow-sm border border-slate-100 p-6">
            <div className="flex items-center justify-between mb-4">
              <span className="text-xs font-black text-slate-400 uppercase tracking-widest">患者基础特征 & V-生命体征</span>
              <button onClick={reset} className="text-rose-500 h-8 w-8 rounded-full hover:bg-rose-50"><i className="fas fa-sync-alt"></i></button>
            </div>
            <div className="grid grid-cols-4 gap-3 mb-6">
              {['ageYears', 'ageMonths', 'ageDays', 'weight'].map((key) => (
                <div key={key}>
                  <label className="block text-[9px] text-slate-400 mb-1 ml-1 font-black uppercase">{key.replace('age', '').replace('weight', 'kg')}</label>
                  <input type="text" value={(patient as any)[key]} onChange={(e) => key === 'weight' ? handleWeightChange(e.target.value) : handleAgeChange(key as any, e.target.value)} placeholder="--" className="w-full bg-slate-50 border-none rounded-xl py-2 px-2 text-center text-lg font-black focus:ring-2 focus:ring-indigo-500 outline-none transition-all" />
                </div>
              ))}
            </div>
            <div className="grid grid-cols-3 gap-3">
              {[
                { id: 'temperature', label: 'T', unit: '°C' }, { id: 'heartRate', label: 'HR', unit: 'bpm' }, { id: 'respRate', label: 'RR', unit: 'bpm' },
                { id: 'bloodPressure', label: 'BP', unit: 'mmHg' }, { id: 'spo2', label: 'SpO2', unit: '%' }, { id: 'crt', label: 'CRT', unit: 's' },
              ].map((vital) => (
                <div key={vital.id}>
                  <label className="block text-[9px] text-slate-400 mb-1 ml-1 font-black uppercase">{vital.label}</label>
