                    <input type="text" value={patient.vitals[vital.id as keyof VitalSigns]} onChange={(e) => handleVitalChange(vital.id as keyof VitalSigns, e.target.value)} placeholder="--" className="w-full bg-slate-50 border-none rounded-xl py-2 px-2 text-center text-sm font-black focus:ring-2 focus:ring-indigo-500 outline-none" />
