                    {item}
                  </div>
                ))}
              </div>
            </div>
            {/* Background Accent */}
            <div className="absolute -right-10 -bottom-10 opacity-20 transform rotate-12">
              <i className="fas fa-heart-pulse text-[150px]"></i>
            </div>
          </div>

          {/* AI Report Card */}
          {aiReport && (
            <div className="bg-white rounded-3xl p-8 shadow-sm border border-slate-100 animate-in slide-in-from-bottom-4 duration-500">
              <div className="flex items-center justify-between mb-6">
