import React, { useState, useMemo } from 'react';
import { TRIAGE_CATEGORIES, TRIAGE_RESULT_CONFIG, HIGH_RISK_FACTORS } from './constants';
import { TriageLevel, PatientState, TriageResult, VitalSigns, Symptom } from './types';
import { getAIClinicalReport } from './services/geminiService';

const App: React.FC = () => {
  const [patient, setPatient] = useState<PatientState>({
    ageYears: '', ageMonths: '', ageDays: '', weight: '',
    vitals: { temperature: '', heartRate: '', respRate: '', bloodPressure: '', spo2: '', crt: '' },
    selectedSymptoms: new Set(), highRiskFactors: new Set(),
  });
  const [activeTab, setActiveTab] = useState(TRIAGE_CATEGORIES[0].id);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [confirmingSymptom, setConfirmingSymptom] = useState<Symptom | null>(null);
  const [showRefTable, setShowRefTable] = useState<'gcs' | 'sh_table' | null>(null);

  // GCS Calculator State
  const [gcsE, setGcsE] = useState<number>(4);
  const [gcsV, setGcsV] = useState<number>(5);
  const [gcsM, setGcsM] = useState<number>(6);

  const gcsTotal = useMemo(() => gcsE + gcsV + gcsM, [gcsE, gcsV, gcsM]);

  const handleAgeChange = (field: keyof Pick<PatientState, 'ageYears' | 'ageMonths' | 'ageDays'>, value: string) => {
    if (value !== '' && !/^\d+$/.test(value)) return;
    setPatient(prev => ({ ...prev, [field]: value }));
  };

  const handleWeightChange = (value: string) => {
    if (value !== '' && !/^\d*\.?\d*$/.test(value)) return;
    setPatient(prev => ({ ...prev, weight: value }));
  };

  const handleVitalChange = (field: keyof VitalSigns, value: string) => {
    if (value !== '' && !/^\d*\.?\d*$/.test(value)) return;
    setPatient(prev => ({
      ...prev,
      vitals: { ...prev.vitals, [field]: value }
    }));
  };

  const toggleSymptom = (symptom: Symptom) => {
    if (patient.selectedSymptoms.has(symptom.id)) {
      setPatient(prev => {
        const next = new Set(prev.selectedSymptoms);
        next.delete(symptom.id);
        return { ...prev, selectedSymptoms: next };
      });
      return;
    }
    if (symptom.helperInfo) {
      setConfirmingSymptom(symptom);
    } else {
      executeToggleSymptom(symptom.id);
    }
  };

  const executeToggleSymptom = (id: string) => {
    setPatient(prev => {
      const next = new Set(prev.selectedSymptoms);
      next.add(id);
      return { ...prev, selectedSymptoms: next };
    });
    setAiReport(null);
    setConfirmingSymptom(null);
  };

  const applyGcsToTriage = () => {
    setPatient(prev => {
      const next = new Set(prev.selectedSymptoms);
      // Remove existing GCS tags
      next.delete('n1');
      next.delete('n2');
      next.delete('n8');

      // Based on constants logic: 3-9 (L1), 10-13 (L2), 14-15 (L4)
      if (gcsTotal <= 9) next.add('n1');
      else if (gcsTotal <= 13) next.add('n2');
      else next.add('n8');

      return { ...prev, selectedSymptoms: next };
    });
    setShowRefTable(null);
  };

  const toggleHighRisk = (id: string) => {
    setPatient(prev => {
      const next = new Set(prev.highRiskFactors);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return { ...prev, highRiskFactors: next };
    });
    setAiReport(null);
  };

  const reset = () => {
    setPatient({
      ageYears: '', ageMonths: '', ageDays: '', weight: '',
      vitals: { temperature: '', heartRate: '', respRate: '', bloodPressure: '', spo2: '', crt: '' },
      selectedSymptoms: new Set(), highRiskFactors: new Set(),
    });
    setAiReport(null);
  };

  const triageReason = useMemo(() => {
    const reasons: string[] = [];
    const years = parseInt(patient.ageYears) || 0;
    const months = parseInt(patient.ageMonths) || 0;
    const days = parseInt(patient.ageDays) || 0;
    const totalMonths = (years * 12) + months;
    const t = parseFloat(patient.vitals.temperature);
    const spo2 = parseFloat(patient.vitals.spo2);
    const crt = parseFloat(patient.vitals.crt);
    const sbp = parseFloat(patient.vitals.bloodPressure);

    if (spo2 > 0) {
      if (spo2 < 90) reasons.push("V: SpO2 < 90% (1级)");
      else if (spo2 <= 94) reasons.push("V: SpO2 90-94% (2级)");
    }
    if (crt >= 3) {
      if (crt > 5) reasons.push("C: CRT > 5s (1级)");
      else reasons.push("C: CRT 3-5s (2级)");
    }
    if (sbp > 0) {
      let isHypotension = false;
      if (years === 0 && months === 0 && days <= 28 && sbp < 60) isHypotension = true;
      else if (totalMonths <= 12 && sbp < 70) isHypotension = true;
      else if (years >= 1 && years <= 10 && sbp < (70 + years * 2)) isHypotension = true;
      else if (years > 10 && sbp < 90) isHypotension = true;
      if (isHypotension) reasons.push("C: 低血压 (1级)");
    }
    if (t > 0) {
      if (t >= 41 || t < 35) reasons.push("V: 体温极值 (2级)");
      if (totalMonths < 3 && t >= 38) reasons.push("V: <3月龄发热 (2级)");
    }

    patient.selectedSymptoms.forEach(id => {
      TRIAGE_CATEGORIES.forEach(cat => {
        const sym = cat.symptoms.find(s => s.id === id);
        if (sym) reasons.push(sym.name);
      });
    });

    patient.highRiskFactors.forEach(id => {
      const factor = HIGH_RISK_FACTORS.find(f => f.id === id);
      if (factor) reasons.push(factor.name);
    });

    return reasons;
  }, [patient]);

  const currentTriage = useMemo((): TriageResult => {
    let baseLevel = 5;
    patient.selectedSymptoms.forEach(id => {
      TRIAGE_CATEGORIES.forEach(cat => {
        const sym = cat.symptoms.find(s => s.id === id);
        if (sym) baseLevel = Math.min(baseLevel, sym.level);
      });
    });
    if (triageReason.some(r => r.includes("(1级)"))) baseLevel = Math.min(baseLevel, 1);
    else if (triageReason.some(r => r.includes("(2级)"))) baseLevel = Math.min(baseLevel, 2);

    const shouldUpgrade = Array.from(patient.highRiskFactors).some(id => {
      return HIGH_RISK_FACTORS.find(f => f.id === id)?.upgrade;
    });
    if (shouldUpgrade && baseLevel > 1) baseLevel -= 1;

    return TRIAGE_RESULT_CONFIG[baseLevel as TriageLevel];
  }, [patient, triageReason]);

  const handleGenerateReport = async () => {
    if (isGenerating) return;
    setIsGenerating(true);
    const symptomsList: string[] = [];
    TRIAGE_CATEGORIES.forEach(cat => {
      cat.symptoms.forEach(s => { if (patient.selectedSymptoms.has(s.id)) symptomsList.push(s.name); });
    });
    patient.highRiskFactors.forEach(id => {
      const f = HIGH_RISK_FACTORS.find(x => x.id === id);
      if (f) symptomsList.push(`[风险] ${f.name}`);
    });
    const report = await getAIClinicalReport(
      { years: patient.ageYears, months: patient.ageMonths, days: patient.ageDays },
      patient.weight, patient.vitals, symptomsList, currentTriage.levelName
    );
    setAiReport(report || "报告生成失败");
    setIsGenerating(false);
    setTimeout(() => { window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' }); }, 150);
  };

  return (
    <div className="min-h-screen p-4 md:p-8 flex flex-col items-center max-w-5xl mx-auto font-sans text-slate-900">
      {/* Helper Modal */}
      {confirmingSymptom && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-sm shadow-xl overflow-hidden border border-slate-200">
            <div className="p-4 bg-indigo-600 text-white flex items-center gap-2">
              <i className="fas fa-stethoscope text-sm"></i>
              <span className="text-sm font-bold">标准核对</span>
            </div>
            <div className="p-5">
              <p className="text-sm font-black text-slate-800 mb-3">{confirmingSymptom.name}</p>
              <div className="p-3 bg-slate-50 rounded-lg border border-slate-100 mb-5 text-[11px] font-bold text-slate-500 leading-relaxed italic whitespace-pre-wrap">
                {confirmingSymptom.helperInfo}
              </div>
              <div className="flex gap-2">
                <button onClick={() => setConfirmingSymptom(null)} className="flex-1 py-2 bg-slate-100 text-slate-500 rounded-lg text-xs font-bold transition-colors">取消</button>
                <button onClick={() => executeToggleSymptom(confirmingSymptom.id)} className="flex-[2] py-2 bg-indigo-600 text-white rounded-lg text-xs font-bold transition-colors">符合标准</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Reference Tables Modal */}
      {showRefTable && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white rounded-3xl w-full max-w-2xl max-h-[90vh] shadow-2xl overflow-hidden flex flex-col border border-slate-200 animate-in zoom-in-95 duration-200">
            <div className="p-6 bg-slate-900 text-white flex items-center justify-between">
              <div className="flex items-center gap-3">
                <i className={`fas ${showRefTable === 'gcs' ? 'fa-brain' : 'fa-table'} text-xl`}></i>
                <span className="font-black tracking-tight">{showRefTable === 'gcs' ? 'P-GCS 自动评分工具' : '上海专家共识参考 (Paediatric CTAS)'}</span>
              </div>
              <button onClick={() => setShowRefTable(null)} className="text-slate-400 hover:text-white"><i className="fas fa-times text-xl"></i></button>
            </div>
            <div className="p-8 overflow-y-auto custom-scrollbar">
              {showRefTable === 'gcs' ? (
                <div className="space-y-8">
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                    {/* Eye Opening */}
                    <div className="space-y-2">
                      <h4 className="text-xs font-black text-indigo-600 uppercase mb-3 flex items-center gap-2">
                        <span className="w-5 h-5 bg-indigo-100 rounded-full flex items-center justify-center">E</span>
                        睁眼反应
                      </h4>
                      {[
                        { s: 4, l: '自发性睁眼' }, { s: 3, l: '语言刺激' }, { s: 2, l: '疼痛刺激' }, { s: 1, l: '无反应' }
                      ].map(i => (
                        <button 
                          key={i.s} 
                          onClick={() => setGcsE(i.s)}
                          className={`w-full flex justify-between items-center text-[11px] p-3 rounded-xl font-bold transition-all border ${
                            gcsE === i.s ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' : 'bg-slate-50 text-slate-600 border-slate-100 hover:bg-slate-100'
                          }`}
                        >
                          <span>{i.l}</span>
                          <span className={gcsE === i.s ? 'text-white/80' : 'text-slate-400'}>{i.s}</span>
                        </button>
                      ))}
                    </div>
                    {/* Verbal */}
                    <div className="space-y-2">
                      <h4 className="text-xs font-black text-indigo-600 uppercase mb-3 flex items-center gap-2">
                        <span className="w-5 h-5 bg-indigo-100 rounded-full flex items-center justify-center">V</span>
                        语言反应
                      </h4>
                      {[
                        { s: 5, l: '喃喃/笑/寻找声源' }, { s: 4, l: '不安/哭吵' }, { s: 3, l: '对疼刺激哭吵' }, { s: 2, l: '对疼刺激呻吟' }, { s: 1, l: '无反应' }
                      ].map(i => (
                        <button 
                          key={i.s} 
                          onClick={() => setGcsV(i.s)}
                          className={`w-full flex justify-between items-center text-[11px] p-3 rounded-xl font-bold transition-all border ${
                            gcsV === i.s ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' : 'bg-slate-50 text-slate-600 border-slate-100 hover:bg-slate-100'
                          }`}
                        >
                          <span>{i.l}</span>
                          <span className={gcsV === i.s ? 'text-white/80' : 'text-slate-400'}>{i.s}</span>
                        </button>
                      ))}
                    </div>
                    {/* Motor */}
                    <div className="space-y-2">
                      <h4 className="text-xs font-black text-indigo-600 uppercase mb-3 flex items-center gap-2">
                        <span className="w-5 h-5 bg-indigo-100 rounded-full flex items-center justify-center">M</span>
                        运动反应
                      </h4>
                      {[
                        { s: 6, l: '自发/按嘱动作' }, { s: 5, l: '疼痛定位' }, { s: 4, l: '疼痛撤退' }, { s: 3, l: '疼痛屈曲(去皮质)' }, { s: 2, l: '疼痛伸展(去大脑)' }, { s: 1, l: '无反应' }
                      ].map(i => (
                        <button 
                          key={i.s} 
                          onClick={() => setGcsM(i.s)}
                          className={`w-full flex justify-between items-center text-[11px] p-3 rounded-xl font-bold transition-all border ${
                            gcsM === i.s ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' : 'bg-slate-50 text-slate-600 border-slate-100 hover:bg-slate-100'
                          }`}
                        >
                          <span>{i.l}</span>
                          <span className={gcsM === i.s ? 'text-white/80' : 'text-slate-400'}>{i.s}</span>
                        </button>
                      ))}
                    </div>
                  </div>

                  {/* Summary Area */}
                  <div className="p-6 bg-slate-900 rounded-3xl text-white flex flex-col md:flex-row items-center justify-between gap-6">
                    <div className="text-center md:text-left">
                      <div className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1">当前评分总计</div>
                      <div className="text-5xl font-black">{gcsTotal} <span className="text-xl opacity-40">/ 15</span></div>
                    </div>
                    <div className="flex-1 max-w-xs text-center md:text-left">
                      <div className="text-[10px] font-black uppercase text-indigo-400 mb-1">病情评估</div>
                      <p className="text-sm font-bold">
                        {gcsTotal >= 14 ? '轻度脑损伤 / 神经状态基本正常' : gcsTotal >= 10 ? '中度脑损伤 (需在15分钟内处理)' : '重度脑损伤 (需立即抢救)'}
                      </p>
                    </div>
                    <button 
                      onClick={applyGcsToTriage}
                      className="px-8 py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black text-sm shadow-xl transition-all active:scale-95 flex items-center gap-2"
                    >
                      <i className="fas fa-check-double"></i>
                      应用至分诊
                    </button>
                  </div>
                </div>
              ) : (
                <div className="space-y-10">
                  {/* Paediatric CTAS RR */}
                  <div>
                    <h4 className="text-sm font-black text-indigo-600 mb-4 flex items-center gap-2">
                      <div className="w-1.5 h-4 bg-indigo-600 rounded"></div>
                      Paediatric CTAS 呼吸频率分级 (次/min)
                    </h4>
                    <div className="overflow-x-auto rounded-xl border border-slate-100">
                      <table className="w-full text-[10px] text-left border-collapse">
                        <thead>
                          <tr className="bg-slate-50">
                            <th className="p-3 border font-black text-slate-500">年龄段</th>
                            <th className="p-3 border font-black text-rose-600">1级 (危急)</th>
                            <th className="p-3 border font-black text-orange-600">2级 (危重)</th>
                            <th className="p-3 border font-black text-amber-600">3级 (急症)</th>
                          </tr>
                        </thead>
                        <tbody>
                          {[
                            { age: '<3月', l1: '>70', l2: '60-70', l3: '50-60' },
                            { age: '3-12月', l1: '>60', l2: '50-60', l3: '40-50' },
                            { age: '1-3岁', l1: '>50', l2: '40-50', l3: '30-40' },
                            { age: '4-11岁', l1: '>40', l2: '30-40', l3: '20-30' },
                            { age: '≥12岁', l1: '>30', l2: '20-30', l3: '15-20' }
                          ].map((row, idx) => (
                            <tr key={idx} className="hover:bg-slate-50 transition-colors">
                              <td className="p-3 border font-bold text-slate-700">{row.age}</td>
                              <td className="p-3 border font-bold">{row.l1}</td>
                              <td className="p-3 border font-bold">{row.l2}</td>
                              <td className="p-3 border font-bold">{row.l3}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>

                  {/* Paediatric CTAS HR */}
                  <div>
                    <h4 className="text-sm font-black text-indigo-600 mb-4 flex items-center gap-2">
                      <div className="w-1.5 h-4 bg-indigo-600 rounded"></div>
                      Paediatric CTAS 心率分级 (次/min)
                    </h4>
                    <div className="overflow-x-auto rounded-xl border border-slate-100">
                      <table className="w-full text-[10px] text-left border-collapse">
                        <thead>
                          <tr className="bg-slate-50">
                            <th className="p-3 border font-black text-slate-500">年龄段</th>
                            <th className="p-3 border font-black text-rose-600">1级 (危急)</th>
                            <th className="p-3 border font-black text-orange-600">2级 (危重)</th>
                            <th className="p-3 border font-black text-amber-600">3级 (急症)</th>
                          </tr>
                        </thead>
                        <tbody>
                          {[
                            { age: '<3月', l1: '>210 或 <80', l2: '180-210', l3: '110-180' },
                            { age: '3-12月', l1: '>190 或 <80', l2: '170-190', l3: '110-170' },
                            { age: '1-3岁', l1: '>180 或 <80', l2: '150-180', l3: '100-150' },
                            { age: '4-11岁', l1: '>160 或 <60', l2: '130-160', l3: '70-130' },
                            { age: '≥12岁', l1: '>140 或 <50', l2: '110-140', l3: '60-110' }
                          ].map((row, idx) => (
                            <tr key={idx} className="hover:bg-slate-50 transition-colors">
                              <td className="p-3 border font-bold text-slate-700">{row.age}</td>
                              <td className="p-3 border font-bold">{row.l1}</td>
                              <td className="p-3 border font-bold">{row.l2}</td>
                              <td className="p-3 border font-bold">{row.l3}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
              )}
            </div>
            <div className="p-4 bg-slate-50 border-t border-slate-100 flex justify-end">
              <button onClick={() => setShowRefTable(null)} className="px-8 py-2.5 bg-slate-900 text-white rounded-xl text-xs font-black transition-all hover:bg-slate-800 active:scale-95">关闭参考</button>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <div className="w-full flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
        <div className="text-center md:text-left">
          <h1 className="text-2xl font-black text-slate-900 tracking-tighter">PETS-LZRYEK</h1>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">儿科急诊预检分诊决策工具</p>
        </div>
        <div className="flex gap-2">
          <button onClick={() => setShowRefTable('gcs')} className="px-4 py-2 bg-indigo-600 text-white rounded-xl text-[10px] font-black shadow-lg shadow-indigo-200 flex items-center gap-2 hover:bg-indigo-700 transition-all active:scale-95">
            <i className="fas fa-brain"></i> P-GCS 自动评分
          </button>
          <button onClick={() => setShowRefTable('sh_table')} className="px-4 py-2 bg-slate-100 text-slate-600 rounded-xl text-[10px] font-black border border-slate-200 flex items-center gap-2 hover:bg-slate-200 transition-all active:scale-95 shadow-sm">
            <i className="fas fa-table"></i> 参考标准
          </button>
        </div>
      </div>

      <div className="w-full grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        {/* Left Column */}
        <div className="lg:col-span-7 space-y-4">
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-5">
            <div className="flex items-center justify-between mb-4">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                <i className="fas fa-heartbeat"></i> 患儿生命体征
              </span>
              <button onClick={reset} className="text-rose-500 h-6 w-6 rounded-md hover:bg-rose-50 transition-colors"><i className="fas fa-sync-alt text-xs"></i></button>
            </div>
            <div className="grid grid-cols-4 gap-2 mb-4">
              {['ageYears', 'ageMonths', 'ageDays', 'weight'].map((key) => (
                <div key={key}>
                  <label className="block text-[8px] text-slate-400 mb-1 ml-1 font-black uppercase">
                    {key === 'ageYears' ? '岁' : key === 'ageMonths' ? '月' : key === 'ageDays' ? '天' : '体重kg'}
                  </label>
                  <input type="text" value={(patient as any)[key]} onChange={(e) => key === 'weight' ? handleWeightChange(e.target.value) : handleAgeChange(key as any, e.target.value)} placeholder="-" className="w-full bg-slate-50 border-none rounded-lg py-2 px-1 text-center text-sm font-black focus:ring-2 focus:ring-indigo-200 outline-none transition-all" />
                </div>
              ))}
            </div>
            <div className="grid grid-cols-3 gap-2">
              {[
                { id: 'temperature', label: 'T (°C)' }, { id: 'heartRate', label: 'HR (bpm)' }, { id: 'respRate', label: 'RR (bpm)' },
                { id: 'bloodPressure', label: 'BP (mmHg)' }, { id: 'spo2', label: 'SpO2 (%)' }, { id: 'crt', label: 'CRT (s)' },
              ].map((vital) => (
                <div key={vital.id}>
                  <label className="block text-[8px] text-slate-400 mb-1 ml-1 font-black uppercase">{vital.label}</label>
                  <input type="text" value={patient.vitals[vital.id as keyof VitalSigns]} onChange={(e) => handleVitalChange(vital.id as keyof VitalSigns, e.target.value)} placeholder="-" className="w-full bg-slate-50 border-none rounded-lg py-2 px-1 text-center text-[13px] font-black focus:ring-2 focus:ring-indigo-200 outline-none transition-all" />
                </div>
              ))}
            </div>
          </div>

          <div className="bg-amber-50/40 rounded-2xl border border-amber-100 p-4">
            <p className="text-[8px] font-black text-amber-600 uppercase mb-2 flex items-center gap-1"><i className="fas fa-exclamation-triangle"></i> 共识风险调节</p>
            <div className="grid grid-cols-2 gap-2">
              {HIGH_RISK_FACTORS.map(f => (
                <button key={f.id} onClick={() => f.helperInfo ? setConfirmingSymptom(f as any) : toggleHighRisk(f.id)} className={`p-2 rounded-lg border text-[9px] text-left transition-all flex items-center gap-2 ${patient.highRiskFactors.has(f.id) ? 'bg-amber-100 border-amber-200 text-amber-900 font-bold' : 'bg-white border-slate-100 text-slate-500 hover:border-slate-200 shadow-sm'}`}>
                  <div className={`w-2 h-2 rounded-full shrink-0 ${patient.highRiskFactors.has(f.id) ? 'bg-amber-600' : 'bg-slate-200'}`}></div>
                  {f.name}
                </button>
              ))}
            </div>
          </div>

          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="p-1 grid grid-cols-4 gap-1 bg-slate-50 border-b border-slate-100">
              {TRIAGE_CATEGORIES.map(cat => (
                <button 
                  key={cat.id} 
                  onClick={() => setActiveTab(cat.id)} 
                  className={`py-2 px-1 rounded-lg text-[9px] font-black transition-all text-center leading-tight flex items-center justify-center h-10 ${
                    activeTab === cat.id ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:bg-slate-200'
                  }`}
                >
                  {cat.name}
                </button>
              ))}
            </div>
            <div className="p-3 grid grid-cols-1 gap-1.5 max-h-[300px] overflow-y-auto custom-scrollbar">
              {TRIAGE_CATEGORIES.find(c => c.id === activeTab)?.symptoms.map(sym => (
                <button 
                  key={sym.id} 
                  onClick={() => toggleSymptom(sym)} 
                  className={`w-full text-left px-4 py-3 rounded-xl border transition-all flex items-center justify-between group ${
                    patient.selectedSymptoms.has(sym.id) ? 'border-indigo-600 bg-indigo-50/40 text-indigo-900 font-black' : 'border-slate-50 bg-slate-50/30 text-slate-700 hover:border-slate-200 shadow-sm'
                  }`}
                >
                  <span className="text-[11px] font-bold">{sym.name}</span>
                  <div className="flex items-center gap-2">
                    {sym.helperInfo && <i className="fas fa-info-circle text-[10px] text-indigo-400 opacity-60"></i>}
                    <i className={`fas ${patient.selectedSymptoms.has(sym.id) ? 'fa-check-circle text-indigo-600' : 'fa-plus-circle text-slate-100 group-hover:text-slate-200'} text-xs`}></i>
                  </div>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Right Column */}
        <div className="lg:col-span-5 space-y-4">
          <div className={`rounded-2xl p-6 shadow-xl text-white relative overflow-hidden transition-all duration-500 ${currentTriage.zoneColor}`}>
            <div className="relative z-10">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <div className="text-[9px] font-black uppercase tracking-widest opacity-80 mb-0.5">分诊结果建议</div>
                  <h2 className="text-2xl font-black mb-1">{currentTriage.levelName}</h2>
                  <div className="text-[10px] font-black bg-black/10 inline-block px-2.5 py-1 rounded-lg">响应时限: {currentTriage.responseTime}</div>
                </div>
                <button 
                  onClick={handleGenerateReport} 
                  disabled={isGenerating}
                  className={`flex items-center gap-1.5 px-3 py-1.5 bg-white/20 backdrop-blur-md rounded-xl text-[9px] font-black border border-white/20 transition-all hover:bg-white/30 shrink-0 shadow-lg ${isGenerating ? 'animate-pulse cursor-wait' : 'active:scale-95'}`}
                >
                  {isGenerating ? <i className="fas fa-circle-notch animate-spin"></i> : <i className="fas fa-magic"></i>}
                  AI 分析
                </button>
              </div>
              <div className="p-3 bg-white/10 rounded-xl border border-white/10 mb-4 text-[11px] font-bold italic leading-relaxed backdrop-blur-sm">
                {currentTriage.description}
              </div>
              <div className="space-y-1.5">
                <div className="text-[8px] font-black uppercase opacity-60 mb-1 tracking-widest">共识推荐处置</div>
                {currentTriage.interventions.map((item, idx) => (
                  <div key={idx} className="flex items-center gap-3 bg-white/5 p-2 rounded-lg text-[10px] font-bold border border-white/5">
                    <span className="w-4 h-4 bg-white/20 rounded flex items-center justify-center text-[8px] font-black shrink-0">{idx + 1}</span>
                    {item}
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="flex flex-wrap gap-1.5">
            {triageReason.length > 0 ? triageReason.map((r, i) => (
              <span key={i} className="px-2.5 py-1 bg-slate-100 text-slate-500 rounded-lg text-[9px] font-bold border border-slate-200/50 shadow-sm">
                <i className="fas fa-bookmark mr-1.5 opacity-40 text-indigo-500"></i> {r}
              </span>
            )) : <span className="text-[9px] text-slate-300 italic px-2">未触及危急重症指标</span>}
          </div>

          {aiReport && (
            <div className="bg-white rounded-2xl p-6 shadow-xl border border-slate-100 animate-in slide-in-from-bottom-4 duration-500">
              <div className="flex items-center justify-between mb-5">
                <div className="flex items-center gap-2.5">
                  <div className="w-7 h-7 bg-slate-900 rounded-xl flex items-center justify-center shadow-lg"><i className="fas fa-robot text-white text-[11px]"></i></div>
                  <span className="text-[11px] font-black uppercase tracking-tight">AI 临床专家评估报告</span>
                </div>
                <button onClick={() => setAiReport(null)} className="text-slate-300 hover:text-rose-500 transition-colors p-1"><i className="fas fa-times text-xs"></i></button>
              </div>
              <div className="prose prose-slate max-w-none text-[10px] font-bold text-slate-600 whitespace-pre-wrap leading-loose overflow-hidden">
                {aiReport}
              </div>
              <div className="mt-6 pt-4 border-t border-slate-50 text-[7px] text-slate-300 uppercase font-black text-center tracking-[0.4em]">
                Smart Pediatric Diagnostic Insight · Gemini 3
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="mt-12 text-[8px] font-black text-slate-300 uppercase tracking-[0.6em] text-center pb-10">
        PETS-LZRYEK · Intelligent Decision Support · V2.8
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { TRIAGE_CATEGORIES, TRIAGE_RESULT_CONFIG, HIGH_RISK_FACTORS } from './constants';
import { TriageLevel, PatientState, TriageResult, VitalSigns, Symptom } from './types';
import { getAIClinicalReport } from './services/geminiService';

const App: React.FC = () => {
  const [patient, setPatient] = useState<PatientState>({
    ageYears: '', ageMonths: '', ageDays: '', weight: '',
    vitals: { temperature: '', heartRate: '', respRate: '', bloodPressure: '', spo2: '', crt: '' },
    selectedSymptoms: new Set(), highRiskFactors: new Set(),
  });
  const [activeTab, setActiveTab] = useState(TRIAGE_CATEGORIES[0].id);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [confirmingSymptom, setConfirmingSymptom] = useState<Symptom | null>(null);
  const [showRefTable, setShowRefTable] = useState<'gcs' | 'sh_table' | 'pts' | null>(null);

  // GCS Calculator State
  const [gcsE, setGcsE] = useState<number>(4);
  const [gcsV, setGcsV] = useState<number>(5);
  const [gcsM, setGcsM] = useState<number>(6);
  const gcsTotal = useMemo(() => gcsE + gcsV + gcsM, [gcsE, gcsV, gcsM]);

  // PTS Calculator State (Table 5)
  const [ptsWeight, setPtsWeight] = useState<number>(2);
  const [ptsAirway, setPtsAirway] = useState<number>(2);
  const [ptsBP, setPtsBP] = useState<number>(2);
  const [ptsCNS, setPtsCNS] = useState<number>(2);
  const [ptsWound, setPtsWound] = useState<number>(2);
  const [ptsFracture, setPtsFracture] = useState<number>(2);
  const ptsTotal = useMemo(() => ptsWeight + ptsAirway + ptsBP + ptsCNS + ptsWound + ptsFracture, 
    [ptsWeight, ptsAirway, ptsBP, ptsCNS, ptsWound, ptsFracture]);

  const handleAgeChange = (field: keyof Pick<PatientState, 'ageYears' | 'ageMonths' | 'ageDays'>, value: string) => {
    if (value !== '' && !/^\d+$/.test(value)) return;
    setPatient(prev => ({ ...prev, [field]: value }));
  };

  const handleWeightChange = (value: string) => {
    if (value !== '' && !/^\d*\.?\d*$/.test(value)) return;
    setPatient(prev => ({ ...prev, weight: value }));
  };

  const handleVitalChange = (field: keyof VitalSigns, value: string) => {
    if (value !== '' && !/^\d*\.?\d*$/.test(value)) return;
    setPatient(prev => ({
      ...prev,
      vitals: { ...prev.vitals, [field]: value }
    }));
  };

  const toggleSymptom = (symptom: Symptom) => {
    if (patient.selectedSymptoms.has(symptom.id)) {
      setPatient(prev => {
        const next = new Set(prev.selectedSymptoms);
        next.delete(symptom.id);
        return { ...prev, selectedSymptoms: next };
      });
      return;
    }
    if (symptom.helperInfo) {
      setConfirmingSymptom(symptom);
    } else {
      executeToggleSymptom(symptom.id);
    }
  };

  const executeToggleSymptom = (id: string) => {
    setPatient(prev => {
      const next = new Set(prev.selectedSymptoms);
      next.add(id);
      return { ...prev, selectedSymptoms: next };
    });
    setAiReport(null);
    setConfirmingSymptom(null);
  };

  const applyGcsToTriage = () => {
    setPatient(prev => {
      const next = new Set(prev.selectedSymptoms);
      next.delete('n1'); next.delete('n2'); next.delete('n8');
      if (gcsTotal <= 9) next.add('n1');
      else if (gcsTotal <= 13) next.add('n2');
      else next.add('n8');
      return { ...prev, selectedSymptoms: next };
    });
    setShowRefTable(null);
  };

  const applyPtsToTriage = () => {
    setPatient(prev => {
      const next = new Set(prev.selectedSymptoms);
      // 根据共识，PTS <= 8 具有潜在生命威胁
      if (ptsTotal <= 8) {
        next.add('s1'); // 标记为严重创伤(1级)
      } else {
        next.delete('s1');
      }
      return { ...prev, selectedSymptoms: next };
    });
    setShowRefTable(null);
  };

  const toggleHighRisk = (id: string) => {
    setPatient(prev => {
      const next = new Set(prev.highRiskFactors);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return { ...prev, highRiskFactors: next };
    });
    setAiReport(null);
  };

  const reset = () => {
    setPatient({
      ageYears: '', ageMonths: '', ageDays: '', weight: '',
      vitals: { temperature: '', heartRate: '', respRate: '', bloodPressure: '', spo2: '', crt: '' },
      selectedSymptoms: new Set(), highRiskFactors: new Set(),
    });
    setAiReport(null);
  };

  const triageReason = useMemo(() => {
    const reasons: string[] = [];
    const years = parseInt(patient.ageYears) || 0;
    const months = parseInt(patient.ageMonths) || 0;
    const days = parseInt(patient.ageDays) || 0;
    const totalMonths = (years * 12) + months;
    const t = parseFloat(patient.vitals.temperature);
    const spo2 = parseFloat(patient.vitals.spo2);
    const crt = parseFloat(patient.vitals.crt);
    const sbp = parseFloat(patient.vitals.bloodPressure);

    if (spo2 > 0 && spo2 < 90) reasons.push("V: SpO2 < 90% (1级)");
    else if (spo2 >= 90 && spo2 <= 94) reasons.push("V: SpO2 90-94% (2级)");

    if (crt > 5) reasons.push("C: CRT > 5s (1级)");
    else if (crt >= 3 && crt <= 5) reasons.push("C: CRT 3-5s (2级)");

    if (sbp > 0) {
      let isHypo = false;
      if (years === 0 && months === 0 && days <= 28 && sbp < 60) isHypo = true;
      else if (totalMonths <= 12 && sbp < 70) isHypo = true;
      else if (years >= 1 && years <= 10 && sbp < (70 + years * 2)) isHypo = true;
      else if (years > 10 && sbp < 90) isHypo = true;
      if (isHypo) reasons.push("C: 低血压 (1级)");
    }

    if (t >= 41 || t < 35) reasons.push("V: 体温极值 (2级)");
    if (totalMonths < 3 && t >= 38) reasons.push("V: <3月龄发热 (2级)");

    patient.selectedSymptoms.forEach(id => {
      TRIAGE_CATEGORIES.forEach(cat => {
        const sym = cat.symptoms.find(s => s.id === id);
        if (sym) reasons.push(sym.name);
      });
    });

    patient.highRiskFactors.forEach(id => {
      const factor = HIGH_RISK_FACTORS.find(f => f.id === id);
      if (factor) reasons.push(factor.name);
    });

    return reasons;
  }, [patient]);

  const currentTriage = useMemo((): TriageResult => {
    let baseLevel = 5;
    patient.selectedSymptoms.forEach(id => {
      TRIAGE_CATEGORIES.forEach(cat => {
        const sym = cat.symptoms.find(s => s.id === id);
        if (sym) baseLevel = Math.min(baseLevel, sym.level);
      });
    });
    if (triageReason.some(r => r.includes("(1级)"))) baseLevel = Math.min(baseLevel, 1);
    else if (triageReason.some(r => r.includes("(2级)"))) baseLevel = Math.min(baseLevel, 2);

    const shouldUpgrade = Array.from(patient.highRiskFactors).some(id => 
      HIGH_RISK_FACTORS.find(f => f.id === id)?.upgrade
    );
    if (shouldUpgrade && baseLevel > 1) baseLevel -= 1;

    return TRIAGE_RESULT_CONFIG[baseLevel as TriageLevel];
  }, [patient, triageReason]);

  const handleGenerateReport = async () => {
    if (isGenerating) return;
    setIsGenerating(true);
    const symptomsList: string[] = [];
    TRIAGE_CATEGORIES.forEach(cat => {
      cat.symptoms.forEach(s => { if (patient.selectedSymptoms.has(s.id)) symptomsList.push(s.name); });
    });
    const report = await getAIClinicalReport(
      { years: patient.ageYears, months: patient.ageMonths, days: patient.ageDays },
      patient.weight, patient.vitals, symptomsList, currentTriage.levelName
    );
    setAiReport(report || "生成失败");
    setIsGenerating(false);
  };

  return (
    <div className="min-h-screen p-4 md:p-8 flex flex-col items-center max-w-5xl mx-auto font-sans text-slate-900 bg-[#f4f7fe] selection:bg-indigo-100">

      {/* Background Decorative Blobs */}
      <div className="fixed top-[-10%] right-[-10%] w-[40%] h-[40%] bg-indigo-200/30 blur-[120px] rounded-full z-0 pointer-events-none"></div>
      <div className="fixed bottom-[-10%] left-[-10%] w-[40%] h-[40%] bg-rose-200/20 blur-[120px] rounded-full z-0 pointer-events-none"></div>

      {/* Helper Modal */}
      {confirmingSymptom && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/20 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white/80 backdrop-blur-2xl rounded-[32px] w-full max-w-sm shadow-2xl overflow-hidden border border-white/40 ring-1 ring-black/5">
            <div className="p-6 bg-indigo-600/90 text-white flex items-center gap-3">
              <div className="w-10 h-10 bg-white/20 rounded-2xl flex items-center justify-center backdrop-blur-sm">
                <i className="fas fa-stethoscope text-lg"></i>
              </div>
              <span className="text-lg font-bold tracking-tight">医学标准核对</span>
            </div>
            <div className="p-8">
              <p className="text-base font-black text-slate-800 mb-4">{confirmingSymptom.name}</p>
              <div className="p-5 bg-black/5 rounded-[24px] mb-8 text-xs font-semibold text-slate-500 leading-relaxed italic border border-white/20">
                {confirmingSymptom.helperInfo}
              </div>
              <div className="flex gap-3">
                <button onClick={() => setConfirmingSymptom(null)} className="flex-1 py-4 bg-white/50 text-slate-500 rounded-2xl text-sm font-bold border border-white/40 transition-all hover:bg-white/80 active:scale-95">取消</button>
                <button onClick={() => executeToggleSymptom(confirmingSymptom.id)} className="flex-[2] py-4 bg-indigo-600 text-white rounded-2xl text-sm font-bold shadow-lg shadow-indigo-200 transition-all hover:bg-indigo-700 active:scale-95">确认符合</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Calculator Modal */}
      {showRefTable && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/10 backdrop-blur-xl animate-in zoom-in-95 duration-300">
          <div className="bg-white/70 backdrop-blur-3xl rounded-[40px] w-full max-w-2xl max-h-[85vh] shadow-2xl overflow-hidden flex flex-col border border-white/50 ring-1 ring-black/5">
            <div className="p-8 flex items-center justify-between border-b border-white/20">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-indigo-600 rounded-[18px] flex items-center justify-center shadow-lg shadow-indigo-100">
                  <i className={`fas ${showRefTable === 'gcs' ? 'fa-brain' : showRefTable === 'pts' ? 'fa-user-injured' : 'fa-table'} text-white text-xl`}></i>
                </div>
                <div>
                  <h3 className="text-xl font-black tracking-tight text-slate-800">
                    {showRefTable === 'gcs' ? 'P-GCS 自动评分' : showRefTable === 'pts' ? 'PTS 小儿创伤评分' : 'Paediatric CTAS 参考'}
                  </h3>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">Automated Clinical Scoring Tool</p>
                </div>
              </div>
              <button onClick={() => setShowRefTable(null)} className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center text-slate-400 hover:bg-rose-50 hover:text-rose-500 transition-all active:scale-90"><i className="fas fa-times"></i></button>
            </div>

            <div className="p-8 overflow-y-auto custom-scrollbar flex-1">
              {showRefTable === 'gcs' ? (
                <div className="space-y-8">
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {/* GCS Categories */}
                    {[
                      { key: 'E', label: '睁眼反应', state: gcsE, setter: setGcsE, options: [{s:4,l:'自发'},{s:3,l:'语言'},{s:2,l:'疼痛'},{s:1,l:'无反应'}] },
                      { key: 'V', label: '语言反应', state: gcsV, setter: setGcsV, options: [{s:5,l:'寻找声源'},{s:4,l:'哭吵/不安'},{s:3,l:'痛哭'},{s:2,l:'呻吟'},{s:1,l:'无反应'}] },
                      { key: 'M', label: '运动反应', state: gcsM, setter: setGcsM, options: [{s:6,l:'自发'},{s:5,l:'定位'},{s:4,l:'撤退'},{s:3,l:'去皮质'},{s:2,l:'去大脑'},{s:1,l:'无反应'}] },
                    ].map(cat => (
                      <div key={cat.key} className="space-y-3">
                        <div className="flex items-center gap-2 mb-4">
                          <span className="w-6 h-6 rounded-lg bg-indigo-100 text-indigo-600 flex items-center justify-center text-[10px] font-black">{cat.key}</span>
                          <span className="text-xs font-black text-slate-500 uppercase">{cat.label}</span>
                        </div>
                        {cat.options.map(opt => (
                          <button key={opt.s} onClick={() => cat.setter(opt.s)} className={`w-full p-4 rounded-2xl text-[11px] font-bold border transition-all flex justify-between items-center ${cat.state === opt.s ? 'bg-indigo-600 text-white border-indigo-600 shadow-md translate-y-[-2px]' : 'bg-white border-slate-100 text-slate-600 hover:border-indigo-200'}`}>
                            <span>{opt.l}</span><span className="opacity-50">{opt.s}</span>
                          </button>
                        ))}
                      </div>
                    ))}
                  </div>
                  <div className="bg-slate-900 rounded-[32px] p-8 text-white flex flex-col md:flex-row items-center justify-between gap-6 shadow-2xl">
                    <div className="text-center md:text-left">
                      <p className="text-[10px] font-black uppercase text-slate-400 mb-1">GCS 总分</p>
                      <div className="text-5xl font-black">{gcsTotal} <span className="text-lg opacity-30">/ 15</span></div>
                    </div>
                    <button onClick={applyGcsToTriage} className="px-10 py-5 bg-indigo-500 hover:bg-indigo-400 rounded-2xl font-black text-sm transition-all active:scale-95 shadow-xl">确认并同步分诊</button>
                  </div>
                </div>
              ) : showRefTable === 'pts' ? (
                <div className="space-y-8">
                  {/* PTS Table Categories */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {[
                      { label: '体重', state: ptsWeight, setter: setPtsWeight, opts: [{v:2,l:'>20kg'},{v:1,l:'10-20kg'},{v:-1,l:'<10kg'}] },
                      { label: '气道', state: ptsAirway, setter: setPtsAirway, opts: [{v:2,l:'正常'},{v:1,l:'可维持'},{v:-1,l:'不可维持'}] },
                      { label: '收缩压', state: ptsBP, setter: setPtsBP, opts: [{v:2,l:'>90mmHg'},{v:1,l:'50-90mmHg'},{v:-1,l:'<50mmHg'}] },
                      { label: '中枢神经', state: ptsCNS, setter: setPtsCNS, opts: [{v:2,l:'清醒'},{v:1,l:'迷糊/短丧失'},{v:-1,l:'昏迷'}] },
                      { label: '开放伤口', state: ptsWound, setter: setPtsWound, opts: [{v:2,l:'无'},{v:1,l:'轻微'},{v:-1,l:'严重/穿透'}] },
                      { label: '骨折', state: ptsFracture, setter: setPtsFracture, opts: [{v:2,l:'无'},{v:1,l:'单处闭合'},{v:-1,l:'多处/开放'}] },
                    ].map(group => (
                      <div key={group.label} className="bg-slate-50/50 p-6 rounded-[28px] border border-white/40">
                        <p className="text-xs font-black text-slate-400 mb-4 uppercase tracking-wider">{group.label}</p>
                        <div className="space-y-2">
                          {group.opts.map(opt => (
                            <button key={opt.v} onClick={() => group.setter(opt.v)} className={`w-full p-3 rounded-xl text-[10px] font-bold border transition-all flex justify-between items-center ${group.state === opt.v ? 'bg-rose-500 text-white border-rose-500 shadow-md' : 'bg-white border-slate-100 text-slate-600 hover:border-rose-200'}`}>
                              <span>{opt.l}</span><span>{opt.v > 0 ? `+${opt.v}` : opt.v}</span>
                            </button>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                  <div className="bg-slate-900 rounded-[32px] p-8 text-white flex flex-col md:flex-row items-center justify-between gap-6 shadow-2xl">
                    <div className="text-center md:text-left">
                      <p className="text-[10px] font-black uppercase text-slate-400 mb-1">PTS 创伤总分</p>
                      <div className="text-5xl font-black">{ptsTotal} <span className="text-lg opacity-30">/ 12</span></div>
                    </div>
                    <div className="flex-1 px-4 text-center md:text-left">
                      <p className="text-[10px] font-black uppercase text-rose-400 mb-1">病情预警</p>
                      <p className="text-xs font-bold">{ptsTotal <= 8 ? '具有生命危险/高度复杂伤' : '相对轻微创伤'}</p>
                    </div>
                    <button onClick={applyPtsToTriage} className="px-10 py-5 bg-rose-500 hover:bg-rose-400 rounded-2xl font-black text-sm transition-all active:scale-95 shadow-xl">标记严重创伤</button>
                  </div>
                </div>
              ) : (
                <div className="space-y-6">
                  {/* Existing SH Table Content */}
                  <div className="p-4 bg-indigo-50/50 rounded-2xl text-[11px] font-bold text-indigo-900 italic">
                    Paediatric CTAS 标准作为全球儿科急诊分诊的金标准。
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Main UI Header */}
      <div className="w-full relative z-10 flex flex-col md:flex-row justify-between items-center mb-10 gap-6">
        <div className="text-center md:text-left">
          <div className="flex items-center justify-center md:justify-start gap-3 mb-1">
            <div className="w-8 h-8 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg"><i className="fas fa-paw"></i></div>
            <h1 className="text-3xl font-[900] text-slate-900 tracking-tighter">PETS<span className="text-indigo-600">.</span></h1>
          </div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] ml-1">Pediatric Triage Suite</p>
        </div>
        <div className="flex gap-3 bg-white/40 backdrop-blur-md p-1.5 rounded-2xl border border-white/60 shadow-sm">
          <button onClick={() => setShowRefTable('gcs')} className="px-4 py-2.5 bg-indigo-600 text-white rounded-xl text-[10px] font-black shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95"><i className="fas fa-brain mr-2"></i>GCS 评分</button>
          <button onClick={() => setShowRefTable('pts')} className="px-4 py-2.5 bg-rose-600 text-white rounded-xl text-[10px] font-black shadow-lg shadow-rose-100 hover:bg-rose-700 transition-all active:scale-95"><i className="fas fa-user-injured mr-2"></i>PTS 评分</button>
          <button onClick={() => setShowRefTable('sh_table')} className="px-4 py-2.5 bg-white/80 text-slate-600 rounded-xl text-[10px] font-black border border-slate-200 hover:bg-slate-50 transition-all active:scale-95"><i className="fas fa-book-medical mr-2"></i>参考标准</button>
        </div>
      </div>

      <div className="w-full grid grid-cols-1 lg:grid-cols-12 gap-8 items-start relative z-10">
        {/* Left Panel */}
        <div className="lg:col-span-7 space-y-6">
          <div className="bg-white/60 backdrop-blur-lg rounded-[36px] shadow-sm border border-white/60 p-8">
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-xl bg-indigo-50 text-indigo-500 flex items-center justify-center"><i className="fas fa-vitals"></i></div>
                <span className="text-xs font-black text-slate-400 uppercase tracking-widest">生命体征录入</span>
              </div>
              <button onClick={reset} className="text-rose-500/60 hover:text-rose-500 transition-colors"><i className="fas fa-undo-alt text-xs"></i></button>
            </div>
            <div className="grid grid-cols-4 gap-4 mb-8">
              {['ageYears', 'ageMonths', 'ageDays', 'weight'].map((key) => (
                <div key={key}>
                  <label className="block text-[9px] font-black text-slate-400 mb-2 ml-1 uppercase">{key.replace('age', '').replace('Years','岁').replace('Months','月').replace('Days','天').replace('weight','体重kg')}</label>
                  <input type="text" value={(patient as any)[key]} onChange={(e) => key === 'weight' ? handleWeightChange(e.target.value) : handleAgeChange(key as any, e.target.value)} placeholder="-" className="w-full h-14 bg-white/50 border-none rounded-2xl text-center text-sm font-black focus:ring-2 focus:ring-indigo-200 outline-none transition-all shadow-inner" />
                </div>
              ))}
            </div>
            <div className="grid grid-cols-3 gap-4">
              {[
                { id: 'temperature', label: 'T (°C)' }, { id: 'heartRate', label: 'HR (bpm)' }, { id: 'respRate', label: 'RR (bpm)' },
                { id: 'bloodPressure', label: 'BP (mmHg)' }, { id: 'spo2', label: 'SpO2 (%)' }, { id: 'crt', label: 'CRT (s)' },
              ].map((vital) => (
                <div key={vital.id}>
                  <label className="block text-[9px] font-black text-slate-400 mb-2 ml-1 uppercase">{vital.label}</label>
                  <input type="text" value={patient.vitals[vital.id as keyof VitalSigns]} onChange={(e) => handleVitalChange(vital.id as keyof VitalSigns, e.target.value)} placeholder="-" className="w-full h-14 bg-white/50 border-none rounded-2xl text-center text-sm font-black focus:ring-2 focus:ring-indigo-200 outline-none transition-all shadow-inner" />
                </div>
              ))}
            </div>
          </div>

          <div className="bg-amber-100/40 backdrop-blur-md rounded-[32px] border border-white/60 p-6">
            <p className="text-[10px] font-black text-amber-600/80 uppercase mb-4 flex items-center gap-2"><i className="fas fa-exclamation-circle"></i> 风险调节因子</p>
            <div className="grid grid-cols-2 gap-3">
              {HIGH_RISK_FACTORS.map(f => (
                <button key={f.id} onClick={() => f.helperInfo ? setConfirmingSymptom(f as any) : toggleHighRisk(f.id)} className={`p-4 rounded-2xl border text-[10px] text-left transition-all flex items-center gap-3 ${patient.highRiskFactors.has(f.id) ? 'bg-amber-200/50 border-amber-300 text-amber-900 font-bold' : 'bg-white/40 border-white text-slate-500 hover:border-amber-200 shadow-sm'}`}>
                  <div className={`w-2.5 h-2.5 rounded-full shrink-0 ${patient.highRiskFactors.has(f.id) ? 'bg-amber-600 shadow-lg shadow-amber-200' : 'bg-slate-200'}`}></div>
                  {f.name}
                </button>
              ))}
            </div>
          </div>

          <div className="bg-white/60 backdrop-blur-lg rounded-[36px] shadow-sm border border-white/60 overflow-hidden">
            <div className="p-2 grid grid-cols-4 gap-2 bg-black/5">
              {TRIAGE_CATEGORIES.map(cat => (
                <button key={cat.id} onClick={() => setActiveTab(cat.id)} className={`py-3 px-2 rounded-2xl text-[10px] font-black transition-all flex items-center justify-center text-center ${activeTab === cat.id ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-white/50'}`}>
                  {cat.name}
                </button>
              ))}
            </div>
            <div className="p-6 grid grid-cols-1 gap-2.5 max-h-[350px] overflow-y-auto custom-scrollbar">
              {TRIAGE_CATEGORIES.find(c => c.id === activeTab)?.symptoms.map(sym => (
                <button key={sym.id} onClick={() => toggleSymptom(sym)} className={`w-full text-left px-6 py-4 rounded-[20px] border transition-all flex items-center justify-between group ${patient.selectedSymptoms.has(sym.id) ? 'border-indigo-600 bg-indigo-100/50 text-indigo-900 font-black' : 'border-white bg-white/40 text-slate-700 hover:border-indigo-200 shadow-sm'}`}>
                  <span className="text-xs font-bold">{sym.name}</span>
                  <div className="flex items-center gap-3">
                    {sym.helperInfo && <i className="fas fa-info-circle text-[11px] text-indigo-300/60"></i>}
                    <i className={`fas ${patient.selectedSymptoms.has(sym.id) ? 'fa-check-circle text-indigo-600' : 'fa-plus-circle text-slate-200 group-hover:text-indigo-200'} text-sm`}></i>
                  </div>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Right Panel (Result) */}
        <div className="lg:col-span-5 space-y-6 sticky top-8">
          <div className={`rounded-[44px] p-10 shadow-2xl text-white relative overflow-hidden transition-all duration-700 ${currentTriage.zoneColor} ring-1 ring-white/20`}>
            {/* Glossy overlay */}
            <div className="absolute top-[-20%] left-[-20%] w-[140%] h-[140%] bg-gradient-to-br from-white/20 to-transparent pointer-events-none"></div>

            <div className="relative z-10">
              <div className="flex justify-between items-start mb-10">
                <div>
                  <div className="text-[10px] font-black uppercase tracking-[0.2em] opacity-70 mb-2">预检分诊专家建议</div>
                  <h2 className="text-4xl font-black mb-3 tracking-tighter">{currentTriage.levelName}</h2>
                  <div className="inline-flex items-center gap-2 bg-black/15 px-4 py-2 rounded-2xl backdrop-blur-md border border-white/10">
                    <i className="far fa-clock text-xs"></i>
                    <span className="text-xs font-black">时限: {currentTriage.responseTime}</span>
                  </div>
                </div>
                <button onClick={handleGenerateReport} disabled={isGenerating} className={`flex items-center gap-2.5 px-6 py-4 bg-white/20 backdrop-blur-xl rounded-3xl text-xs font-black border border-white/20 transition-all hover:bg-white/30 shadow-xl ${isGenerating ? 'animate-pulse opacity-50' : 'active:scale-90'}`}>
                  {isGenerating ? <i className="fas fa-circle-notch animate-spin"></i> : <i className="fas fa-magic"></i>}
                  AI 分析
                </button>
              </div>

              <div className="p-6 bg-white/10 rounded-[28px] border border-white/10 mb-8 text-sm font-bold italic leading-relaxed backdrop-blur-sm">
                "{currentTriage.description}"
              </div>

              <div className="space-y-3">
                <div className="text-[10px] font-black uppercase opacity-60 mb-2 tracking-widest">标准处置路径 (Paediatric Triage Path)</div>
                {currentTriage.interventions.map((item, idx) => (
                  <div key={idx} className="flex items-center gap-4 bg-white/5 p-4 rounded-2xl text-xs font-bold border border-white/5 backdrop-blur-sm">
                    <span className="w-6 h-6 bg-white/20 rounded-lg flex items-center justify-center text-[10px] font-black shrink-0">{idx + 1}</span>
                    {item}
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="flex flex-wrap gap-2 px-2">
            {triageReason.length > 0 ? triageReason.map((r, i) => (
              <span key={i} className="px-4 py-2 bg-white/60 backdrop-blur-md text-slate-500 rounded-2xl text-[10px] font-black border border-white/80 shadow-sm flex items-center gap-2">
                <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full"></div>
                {r}
              </span>
            )) : <span className="text-[11px] text-slate-400 italic font-medium">无危急症状标记</span>}
          </div>

          {aiReport && (
            <div className="bg-white/80 backdrop-blur-2xl rounded-[40px] p-10 shadow-2xl border border-white/60 animate-in slide-in-from-bottom-8 duration-500">
              <div className="flex items-center justify-between mb-8">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 bg-slate-900 rounded-[14px] flex items-center justify-center shadow-lg"><i className="fas fa-robot text-white text-sm"></i></div>
                  <div>
                    <span className="text-xs font-black uppercase tracking-tight text-slate-800">专家深度评估报告</span>
                    <p className="text-[8px] font-bold text-slate-400">Deep Clinical Evaluation</p>
                  </div>
                </div>
                <button onClick={() => setAiReport(null)} className="w-8 h-8 rounded-full bg-slate-100 text-slate-300 hover:text-rose-500 transition-colors"><i className="fas fa-times text-xs"></i></button>
              </div>
              <div className="prose prose-slate max-w-none text-[11px] font-bold text-slate-600 whitespace-pre-wrap leading-[1.8] tracking-tight">
                {aiReport}
              </div>
              <div className="mt-10 pt-6 border-t border-slate-100 text-[8px] text-slate-300 uppercase font-black text-center tracking-[0.5em]">
                Secure Pediatric Insight · Gemini Professional
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="mt-20 mb-12 text-[9px] font-black text-slate-300 uppercase tracking-[0.6em] text-center">
        PETS-LZRYEK · Smart Triage Protocol · Build 3.0
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { TRIAGE_CATEGORIES, TRIAGE_RESULT_CONFIG, HIGH_RISK_FACTORS } from './constants';
import { TriageLevel, PatientState, TriageResult, VitalSigns, Symptom } from './types';
import { getAIClinicalReport } from './services/geminiService';

const App: React.FC = () => {
  const [patient, setPatient] = useState<PatientState>({
    ageYears: '', ageMonths: '', ageDays: '', weight: '',
    vitals: { temperature: '', heartRate: '', respRate: '', bloodPressure: '', spo2: '', crt: '' },
    selectedSymptoms: new Set(), highRiskFactors: new Set(),
  });
  const [activeTab, setActiveTab] = useState(TRIAGE_CATEGORIES[0].id);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [confirmingSymptom, setConfirmingSymptom] = useState<Symptom | null>(null);
  const [showRefTable, setShowRefTable] = useState<'gcs' | 'sh_table' | 'pts' | null>(null);

  // GCS Calculator State
  const [gcsE, setGcsE] = useState<number>(4);
  const [gcsV, setGcsV] = useState<number>(5);
  const [gcsM, setGcsM] = useState<number>(6);
  const gcsTotal = useMemo(() => gcsE + gcsV + gcsM, [gcsE, gcsV, gcsM]);

  // PTS Calculator State (Table 5)
  const [ptsWeight, setPtsWeight] = useState<number>(2);
  const [ptsAirway, setPtsAirway] = useState<number>(2);
  const [ptsBP, setPtsBP] = useState<number>(2);
  const [ptsCNS, setPtsCNS] = useState<number>(2);
  const [ptsWound, setPtsWound] = useState<number>(2);
  const [ptsFracture, setPtsFracture] = useState<number>(2);
  const ptsTotal = useMemo(() => ptsWeight + ptsAirway + ptsBP + ptsCNS + ptsWound + ptsFracture, 
    [ptsWeight, ptsAirway, ptsBP, ptsCNS, ptsWound, ptsFracture]);

  const handleAgeChange = (field: keyof Pick<PatientState, 'ageYears' | 'ageMonths' | 'ageDays'>, value: string) => {
    if (value !== '' && !/^\d+$/.test(value)) return;
    setPatient(prev => ({ ...prev, [field]: value }));
  };

  const handleWeightChange = (value: string) => {
    if (value !== '' && !/^\d*\.?\d*$/.test(value)) return;
    setPatient(prev => ({ ...prev, weight: value }));
  };

  const handleVitalChange = (field: keyof VitalSigns, value: string) => {
    if (value !== '' && !/^\d*\.?\d*$/.test(value)) return;
    setPatient(prev => ({
      ...prev,
      vitals: { ...prev.vitals, [field]: value }
    }));
  };

  const toggleSymptom = (symptom: Symptom) => {
    if (patient.selectedSymptoms.has(symptom.id)) {
      setPatient(prev => {
        const next = new Set(prev.selectedSymptoms);
        next.delete(symptom.id);
        return { ...prev, selectedSymptoms: next };
      });
      return;
    }
    if (symptom.helperInfo) {
      setConfirmingSymptom(symptom);
    } else {
      executeToggleSymptom(symptom.id);
    }
  };

  const executeToggleSymptom = (id: string) => {
    setPatient(prev => {
      const next = new Set(prev.selectedSymptoms);
      next.add(id);
      return { ...prev, selectedSymptoms: next };
    });
    setAiReport(null);
    setConfirmingSymptom(null);
  };

  const applyGcsToTriage = () => {
    setPatient(prev => {
      const next = new Set(prev.selectedSymptoms);
      next.delete('n1'); next.delete('n2'); next.delete('n8');
      if (gcsTotal <= 9) next.add('n1');
      else if (gcsTotal <= 13) next.add('n2');
      else next.add('n8');
      return { ...prev, selectedSymptoms: next };
    });
    setShowRefTable(null);
  };

  const applyPtsToTriage = () => {
    setPatient(prev => {
      const next = new Set(prev.selectedSymptoms);
      if (ptsTotal <= 8) next.add('s1');
      else next.delete('s1');
      return { ...prev, selectedSymptoms: next };
    });
    setShowRefTable(null);
  };

  // Allergy Management Logic
  const isAnaphylaxisActive = useMemo(() => {
    const allergySymptoms = ['a1', 'a2', 'a3', 'a4'];
    return allergySymptoms.some(id => patient.selectedSymptoms.has(id));
  }, [patient.selectedSymptoms]);

  const drugDosages = useMemo(() => {
    const w = parseFloat(patient.weight) || 0;
    const age = parseInt(patient.ageYears) || 0;
    if (w <= 0) return null;

    // Epinephrine: 0.01mg/kg IM, max 0.3mg
    const epiRaw = w * 0.01;
    const epiFinal = Math.min(epiRaw, 0.3).toFixed(2);

    // Methylprednisolone: 1-2mg/kg
    const mpMin = (w * 1).toFixed(1);
    const mpMax = (w * 2).toFixed(1);

    // Hydrocortisone: 2-4mg/kg
    const hcMin = (w * 2).toFixed(1);
    const hcMax = (w * 4).toFixed(1);

    // H1 Blocker
    const antihistamine = age < 6 ? '5 mg' : '10 mg';

    return { epiFinal, mpMin, mpMax, hcMin, hcMax, antihistamine };
  }, [patient.weight, patient.ageYears]);

  const toggleHighRisk = (id: string) => {
    setPatient(prev => {
      const next = new Set(prev.highRiskFactors);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return { ...prev, highRiskFactors: next };
    });
    setAiReport(null);
  };

  const reset = () => {
    setPatient({
      ageYears: '', ageMonths: '', ageDays: '', weight: '',
      vitals: { temperature: '', heartRate: '', respRate: '', bloodPressure: '', spo2: '', crt: '' },
      selectedSymptoms: new Set(), highRiskFactors: new Set(),
    });
    setAiReport(null);
  };

  const triageReason = useMemo(() => {
    const reasons: string[] = [];
    const years = parseInt(patient.ageYears) || 0;
    const months = parseInt(patient.ageMonths) || 0;
    const days = parseInt(patient.ageDays) || 0;
    const totalMonths = (years * 12) + months;
    const t = parseFloat(patient.vitals.temperature);
    const spo2 = parseFloat(patient.vitals.spo2);
    const crt = parseFloat(patient.vitals.crt);
    const sbp = parseFloat(patient.vitals.bloodPressure);

    if (spo2 > 0 && spo2 < 90) reasons.push("V: SpO2 < 90% (1级)");
    else if (spo2 >= 90 && spo2 <= 94) reasons.push("V: SpO2 90-94% (2级)");

    if (crt > 5) reasons.push("C: CRT > 5s (1级)");
    else if (crt >= 3 && crt <= 5) reasons.push("C: CRT 3-5s (2级)");

    if (sbp > 0) {
      let isHypo = false;
      if (years === 0 && months === 0 && days <= 28 && sbp < 60) isHypo = true;
      else if (totalMonths <= 12 && sbp < 70) isHypo = true;
      else if (years >= 1 && years <= 10 && sbp < (70 + years * 2)) isHypo = true;
      else if (years > 10 && sbp < 90) isHypo = true;
      if (isHypo) reasons.push("C: 低血压 (1级)");
    }

    if (t >= 41 || t < 35) reasons.push("V: 体温极值 (2级)");
    if (totalMonths < 3 && t >= 38) reasons.push("V: <3月龄发热 (2级)");

    patient.selectedSymptoms.forEach(id => {
      TRIAGE_CATEGORIES.forEach(cat => {
        const sym = cat.symptoms.find(s => s.id === id);
        if (sym) reasons.push(sym.name);
      });
    });

    patient.highRiskFactors.forEach(id => {
      const factor = HIGH_RISK_FACTORS.find(f => f.id === id);
      if (factor) reasons.push(factor.name);
    });

    return reasons;
  }, [patient]);

  const currentTriage = useMemo((): TriageResult => {
    let baseLevel = 5;
    patient.selectedSymptoms.forEach(id => {
      TRIAGE_CATEGORIES.forEach(cat => {
        const sym = cat.symptoms.find(s => s.id === id);
        if (sym) baseLevel = Math.min(baseLevel, sym.level);
      });
    });
    if (triageReason.some(r => r.includes("(1级)"))) baseLevel = Math.min(baseLevel, 1);
    else if (triageReason.some(r => r.includes("(2级)"))) baseLevel = Math.min(baseLevel, 2);

    const shouldUpgrade = Array.from(patient.highRiskFactors).some(id => 
      HIGH_RISK_FACTORS.find(f => f.id === id)?.upgrade
    );
    if (shouldUpgrade && baseLevel > 1) baseLevel -= 1;

    return TRIAGE_RESULT_CONFIG[baseLevel as TriageLevel];
  }, [patient, triageReason]);

  const handleGenerateReport = async () => {
    if (isGenerating) return;
    setIsGenerating(true);
    const symptomsList: string[] = [];
    TRIAGE_CATEGORIES.forEach(cat => {
      cat.symptoms.forEach(s => { if (patient.selectedSymptoms.has(s.id)) symptomsList.push(s.name); });
    });
    const report = await getAIClinicalReport(
      { years: patient.ageYears, months: patient.ageMonths, days: patient.ageDays },
      patient.weight, patient.vitals, symptomsList, currentTriage.levelName
    );
    setAiReport(report || "生成失败");
    setIsGenerating(false);
  };

  return (
    <div className="min-h-screen p-4 md:p-8 flex flex-col items-center max-w-5xl mx-auto font-sans text-slate-900 bg-[#f8f9ff] selection:bg-indigo-100">

      {/* Dynamic Background Blobs */}
      <div className="fixed top-[-5%] right-[-5%] w-[50%] h-[50%] bg-blue-200/20 blur-[100px] rounded-full z-0 pointer-events-none"></div>
      <div className="fixed bottom-[-5%] left-[-5%] w-[50%] h-[50%] bg-indigo-200/20 blur-[100px] rounded-full z-0 pointer-events-none"></div>

      {/* Helper Modal */}
      {confirmingSymptom && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/10 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white/90 backdrop-blur-2xl rounded-[36px] w-full max-w-sm shadow-2xl border border-white/40 ring-1 ring-black/5 overflow-hidden">
            <div className="p-6 bg-indigo-600/90 text-white flex items-center gap-3">
              <i className="fas fa-stethoscope text-lg"></i>
              <span className="text-lg font-bold tracking-tight">医学判定核对</span>
            </div>
            <div className="p-8">
              <p className="text-base font-black text-slate-800 mb-4">{confirmingSymptom.name}</p>
              <div className="p-5 bg-black/5 rounded-[24px] mb-8 text-xs font-semibold text-slate-500 leading-relaxed italic">
                {confirmingSymptom.helperInfo}
              </div>
              <div className="flex gap-3">
                <button onClick={() => setConfirmingSymptom(null)} className="flex-1 py-4 bg-white/60 text-slate-500 rounded-2xl text-sm font-bold border border-white transition-all active:scale-95">取消</button>
                <button onClick={() => executeToggleSymptom(confirmingSymptom.id)} className="flex-[2] py-4 bg-indigo-600 text-white rounded-2xl text-sm font-bold shadow-lg shadow-indigo-100 transition-all active:scale-95">确认符合</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Reference Calculators Modal */}
      {showRefTable && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/10 backdrop-blur-xl animate-in zoom-in-95 duration-300">
          <div className="bg-white/80 backdrop-blur-3xl rounded-[40px] w-full max-w-2xl max-h-[85vh] shadow-2xl overflow-hidden flex flex-col border border-white/60 ring-1 ring-black/5">
            <div className="p-8 flex items-center justify-between border-b border-white/30">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-indigo-600 rounded-[20px] flex items-center justify-center shadow-lg shadow-indigo-100">
                  <i className={`fas ${showRefTable === 'gcs' ? 'fa-brain' : showRefTable === 'pts' ? 'fa-user-injured' : 'fa-table'} text-white text-xl`}></i>
                </div>
                <div>
                  <h3 className="text-xl font-black tracking-tight text-slate-800">
                    {showRefTable === 'gcs' ? 'P-GCS 自动评分' : showRefTable === 'pts' ? 'PTS 小儿创伤评分' : 'Paediatric CTAS 参考'}
                  </h3>
