                      { key: 'V', label: '语言反应', state: gcsV, setter: setGcsV, options: [{s:5,l:'笑/搜声'},{s:4,l:'不安'},{s:3,l:'痛哭'},{s:2,l:'呻吟'},{s:1,l:'无'}] },
                      { key: 'M', label: '运动反应', state: gcsM, setter: setGcsM, options: [{s:6,l:'自发'},{s:5,l:'定位'},{s:4,l:'撤退'},{s:3,l:'屈曲'},{s:2,l:'伸展'},{s:1,l:'无'}] },
