                          <span className="w-6 h-6 rounded-lg bg-indigo-100 text-indigo-600 flex items-center justify-center text-[10px] font-black">{cat.key}</span>
                          <span className="text-xs font-black text-slate-500 uppercase">{cat.label}</span>
                        </div>
                        {cat.options.map(opt => (
                          <button key={opt.s} onClick={() => cat.setter(opt.s)} className={`w-full p-4 rounded-2xl text-[11px] font-bold border transition-all flex justify-between items-center ${cat.state === opt.s ? 'bg-indigo-600 text-white border-indigo-600 shadow-md translate-y-[-2px]' : 'bg-white/50 border-slate-100 text-slate-600 hover:border-indigo-200'}`}>
