                    <button onClick={applyPtsToTriage} className="px-10 py-5 bg-rose-500 hover:bg-rose-400 rounded-2xl font-black text-sm shadow-xl active:scale-95 transition-all">确认同步</button>
                  </div>
                </div>
              ) : null}
            </div>
          </div>
        </div>
      )}

      {/* Main Header */}
      <div className="w-full relative z-10 flex flex-col md:flex-row justify-between items-center mb-10 gap-6">
