        </div>
        <div className="flex gap-3 bg-white/40 backdrop-blur-md p-1.5 rounded-2xl border border-white/60 shadow-sm">
          <button onClick={() => setShowRefTable('gcs')} className="px-4 py-2.5 bg-indigo-600 text-white rounded-xl text-[10px] font-black shadow-lg hover:bg-indigo-700 transition-all active:scale-95">P-GCS</button>
          <button onClick={() => setShowRefTable('pts')} className="px-4 py-2.5 bg-rose-600 text-white rounded-xl text-[10px] font-black shadow-lg hover:bg-rose-700 transition-all active:scale-95">PTS 创伤</button>
          <button onClick={() => setShowRefTable('sh_table')} className="px-4 py-2.5 bg-white/80 text-slate-600 rounded-xl text-[10px] font-black border border-slate-200 hover:bg-white transition-all active:scale-95">参考共识</button>
        </div>
      </div>

      <div className="w-full grid grid-cols-1 lg:grid-cols-12 gap-8 items-start relative z-10">
