            <div className="grid grid-cols-2 gap-3">
              {HIGH_RIS_FACTORS.map(f => (
                <button key={f.id} onClick={() => f.helperInfo ? setConfirmingSymptom(f as any) : toggleHighRisk(f.id)} className={`p-4 rounded-2xl border text-[10px] text-left transition-all flex items-center gap-3 ${patient.highRiskFactors.has(f.id) ? 'bg-amber-200/50 border-amber-300 text-amber-900 font-bold' : 'bg-white/40 border-white text-slate-500 hover:border-amber-200'}`}>
                  <div className={`w-2.5 h-2.5 rounded-full shrink-0 ${patient.highRiskFactors.has(f.id) ? 'bg-amber-600' : 'bg-slate-200'}`}></div>
                  {f.name}
                </button>
              ))}
            </div>
          </div>

          {/* Anaphylaxis Emergency Protocol Panel */}
          {isAnaphylaxisActive && (
