                    </div>
                  ) : (
                    <p className="text-xs font-bold text-slate-400 italic">请先录入体重以计算精确剂量</p>
                  )}
                </div>

                {/* Secondary Medications */}
                <div className="bg-white/70 p-6 rounded-[28px] border border-rose-100">
                  <p className="text-[10px] font-black text-indigo-500 uppercase mb-3 flex items-center gap-2">
                    <i className="fas fa-pills"></i> 二线药物推荐
                  </p>
                  {drugDosages ? (
                    <div className="space-y-3">
                      <div>
                        <span className="text-[10px] font-black text-slate-400 uppercase">甲泼尼龙:</span>
                        <div className="text-sm font-black text-slate-800">{drugDosages.mpMin}~{drugDosages.mpMax} mg</div>
                      </div>
                      <div>
                        <span className="text-[10px] font-black text-slate-400 uppercase">抗组胺药:</span>
                        <div className="text-sm font-black text-slate-800">{drugDosages.antihistamine} (西替利嗪/氯雷他定)</div>
                      </div>
                    </div>
                  ) : (
                    <p className="text-xs font-bold text-slate-400 italic">待录入数据...</p>
                  )}
                </div>
              </div>

              {/* Action Checklist */}
              <div className="space-y-3">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">核心处置步骤 (根据专家共识)</p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  {[
                    '体位：平卧、抬高下肢 (维持回心血量)',
                    '保持气道通畅，大流量给氧 (5-10 L/min)',
                    '快速建立静脉通路，备好晶体液复苏',
                    '心电、血压、经皮氧饱和度持续监护',
                  ].map((step, i) => (
                    <div key={i} className="flex items-center gap-3 bg-white/40 p-4 rounded-2xl text-[11px] font-bold border border-white/60">
                      <div className="w-5 h-5 bg-rose-100 text-rose-600 rounded-lg flex items-center justify-center text-[9px] font-black shrink-0">{i+1}</div>
                      {step}
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          <div className="bg-white/60 backdrop-blur-lg rounded-[36px] shadow-sm border border-white/60 overflow-hidden">
            <div className="p-2 grid grid-cols-4 gap-2 bg-black/5">
              {TRIAGE_CATEGORIES.map(cat => (
                <button key={cat.id} onClick={() => setActiveTab(cat.id)} className={`py-3 px-2 rounded-2xl text-[10px] font-black transition-all h-12 flex items-center justify-center ${activeTab === cat.id ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-white/50'}`}>
                  {cat.name}
                </button>
              ))}
            </div>
            <div className="p-6 grid grid-cols-1 gap-3 max-h-[350px] overflow-y-auto custom-scrollbar">
              {TRIAGE_CATEGORIES.find(c => c.id === activeTab)?.symptoms.map(sym => (
                <button key={sym.id} onClick={() => toggleSymptom(sym)} className={`w-full text-left px-6 py-4 rounded-[22px] border transition-all flex items-center justify-between group ${patient.selectedSymptoms.has(sym.id) ? 'border-indigo-600 bg-indigo-100/40 text-indigo-900 font-black' : 'border-white bg-white/40 text-slate-700 hover:border-indigo-200'}`}>
                  <span className="text-xs font-bold">{sym.name}</span>
                  <div className="flex items-center gap-3">
                    {sym.helperInfo && <i className="fas fa-info-circle text-[11px] text-indigo-300"></i>}
                    <i className={`fas ${patient.selectedSymptoms.has(sym.id) ? 'fa-check-circle text-indigo-600' : 'fa-plus-circle text-slate-100 group-hover:text-indigo-200'} text-sm`}></i>
                  </div>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Right Column: Result Display */}
        <div className="lg:col-span-5 space-y-6 sticky top-8">
          <div className={`rounded-[48px] p-10 shadow-2xl text-white relative overflow-hidden transition-all duration-700 ${currentTriage.zoneColor} ring-1 ring-white/20`}>
            {/* Glossy IOS Overlay */}
            <div className="absolute inset-0 bg-gradient-to-br from-white/10 to-transparent pointer-events-none"></div>

            <div className="relative z-10">
              <div className="flex justify-between items-start mb-10">
                <div>
                  <div className="text-[10px] font-black uppercase tracking-[0.2em] opacity-80 mb-2">预检决策输出</div>
                  <h2 className="text-4xl font-[900] mb-3 tracking-tighter">{currentTriage.levelName}</h2>
                  <div className="inline-flex items-center gap-2 bg-black/10 px-4 py-2 rounded-2xl border border-white/5">
                    <i className="far fa-clock text-xs"></i>
                    <span className="text-xs font-black">时限: {currentTriage.responseTime}</span>
                  </div>
                </div>
                <button onClick={handleGenerateReport} disabled={isGenerating} className={`flex items-center gap-2.5 px-6 py-4 bg-white/20 backdrop-blur-xl rounded-[28px] text-[10px] font-black border border-white/10 shadow-lg ${isGenerating ? 'animate-pulse' : 'active:scale-90 hover:bg-white/30'}`}>
                  {isGenerating ? <i className="fas fa-circle-notch animate-spin"></i> : <i className="fas fa-magic"></i>}
                  AI 分析
                </button>
              </div>

              <div className="p-6 bg-black/5 rounded-[32px] border border-white/5 mb-8 text-sm font-bold italic leading-relaxed backdrop-blur-sm">
                "{currentTriage.description}"
              </div>

              <div className="space-y-3">
                <div className="text-[9px] font-black uppercase opacity-60 mb-2 tracking-widest">分流处置路径</div>
                {currentTriage.interventions.map((item, idx) => (
                  <div key={idx} className="flex items-center gap-4 bg-white/5 p-4 rounded-2xl text-xs font-bold border border-white/5 backdrop-blur-sm">
                    <span className="w-6 h-6 bg-white/20 rounded-lg flex items-center justify-center text-[9px] font-black shrink-0">{idx + 1}</span>
                    {item}
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="flex flex-wrap gap-2 px-2">
            {triageReason.length > 0 ? triageReason.map((r, i) => (
              <span key={i} className="px-4 py-2 bg-white/70 backdrop-blur-md text-slate-500 rounded-2xl text-[10px] font-black border border-white shadow-sm flex items-center gap-2">
                <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full"></div>
                {r}
              </span>
            )) : <span className="text-[11px] text-slate-300 italic font-medium">无危急症状触发指标</span>}
          </div>

          {aiReport && (
            <div className="bg-white/90 backdrop-blur-2xl rounded-[44px] p-10 shadow-2xl border border-white ring-1 ring-black/5 animate-in slide-in-from-bottom-8 duration-500">
              <div className="flex items-center justify-between mb-8">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 bg-slate-900 rounded-[14px] flex items-center justify-center shadow-lg"><i className="fas fa-robot text-white text-sm"></i></div>
                  <div>
                    <span className="text-xs font-black uppercase tracking-tight text-slate-800">AI 临床决策评估报告</span>
                    <p className="text-[8px] font-bold text-slate-400 tracking-widest">GEMINI INTELLIGENCE REPORT</p>
                  </div>
                </div>
                <button onClick={() => setAiReport(null)} className="w-8 h-8 rounded-full bg-slate-50 text-slate-300 hover:text-rose-500 transition-colors"><i className="fas fa-times text-xs"></i></button>
              </div>
              <div className="prose prose-slate max-w-none text-[11px] font-bold text-slate-600 whitespace-pre-wrap leading-loose tracking-tight overflow-hidden">
                {aiReport}
              </div>
              <div className="mt-10 pt-6 border-t border-slate-100 text-[8px] text-slate-300 uppercase font-black text-center tracking-[0.5em]">
                Smart Pediatric Diagnosis · PETS Core
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="mt-20 mb-12 text-[9px] font-black text-slate-300 uppercase tracking-[0.7em] text-center opacity-50">
        PETS-LZRYEK · Clinical Decision Support · V3.1
      </div>
    </div>
  );
};

